SELECT 'moj-all-verified-judgments-review-002-chunk-048' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7b29f722-3c23-55ab-869e-672eda77dc38","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم عن طريق رسالة جوال -مطالبة املدعي باملجازاة -إقرار املدعى عليه مبا جاء يف الدعوى -إدانة املدعى عليه.","document_number":"34175650","case_number":"34107315","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم عن طريق رسالة جوال -مطالبة املدعي باملجازاة -إقرار املدعى عليه مبا جاء يف الدعوى -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/1 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34175650 :‬‬\n                   ‫َر ْق ُم الدعوى‪34107315 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34235173‬تاريخه‪1434/6/10:‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والشــتم عــن طريــق رســالة‬\n‫جــوال ‪ -‬مطالبــة املدعــي باملجــازاة ‪ -‬إقــرار املدعــى عليــه مبــا جــاء يف‬\n                                               ‫الدعــوى ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n‫قــال يف كشــاف القنــاع‪« :‬كل مــا فيــه إيــذاء ليــس بصريــح يف الزنــى‬\n         ‫فيعــزر بــه الرتكابــه معصيــة وكفــا لــه عــن أذى املعصومــن»‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليــه بأنــه أرســل لــه رســالة جــوال تتضمــن‬\n‫شــتمه لــه مبــا جــاء يف دعــواه‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n‫ذلــك‪ -‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي وقــدم اعتــذاره عمــا‬\n‫بــدر منــه‪ -‬مــا أقــدم عليــه املدعــى عليــه أمــر محــرم يوجــب تعزيــره ألن‬\n‫فيــه إيــذاء لغيــره‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه مبــا نســب إليــه‬\n‫وقــررت جلــده خمــس جلــدات بحضــور املدعــي‪ -‬قنــع املدعــي باحلكــم‬\n‫وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف املوافقــة‬\n                                                                  ‫علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                      ‫‪316‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بينبــع املســاعد برقــم ‪ 34107315‬وتاريــخ ‪1434/03/04‬ه ـ‬\n      ‫واملقيــدة باحملكمــة برقــم ‪ 34562323‬وتاريــخ ‪1434/03/04‬ه ـ ففــي‬\n      ‫يــوم األربعــاء املوافــق ‪1434/03/18‬ه ـ الســاعة الثامنــة صباحــا افتتحــت‬\n      ‫اجللســة وفيها حضر ‪ ...‬املدعي ســعودي اجلنســية مبوجب الســجل املدني‬\n      ‫رقــم ‪ ....‬ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه شــرعا رغــم تبلغــه‬\n      ‫باملوعــد شــخصيا حســب إفــادة محضــري اخلصــوم برقــم ‪34562323‬‬\n      ‫يف ‪1434/03/13‬ه ـ لــذا قــررت النظــر يف الدعــوى فســألت املدعــي‬\n      ‫عــن دعــواه فقــرر قائــا ان املدعــى عليــه شــتمني عبــر رســالة جــوال‬\n      ‫وقــال عنــي اننــي واطــي اطلــب احلكــم عليــه وتعزيــره لقــاء ذلــك هــذه‬\n      ‫دعــواي وبطلــب البينــة مــن املدعــي طلــب إمهالــه إلحضارهــا فأجيــب‬\n      ‫لطلبــه ولــذا رفعــت اجللســة ‪.‬ويف يــوم االثنــن املوافــق ‪ 1434/04/01‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 08:30‬وفيهــا حضــر املدعــي وحضــر حلضــوره‬\n      ‫املدعــى عليــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وبســؤال‬\n      ‫املدعــى عليــه عمــا ذكــره املدعــي أجــاب قائــا بــأن مــا ذكــره املدعــي‬\n      ‫صحيــح وأنــا اعتــذر عمــا حصــل منــي هكــذا أجــاب وبنــاء علــى مــا ســبق‬\n      ‫مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه بصحــة مــا ذكــره املدعــي‬\n      ‫وحلرمــة ايــذاء النــاس والتلفــظ عليهــم قــال يف كشــاف القنــاع ( ‪..‬مــن‬\n      ‫كل مــا فيــه ايــذاء ليــس بصريــح يف الزنــى فيعــزر بــه الرتكابــه معصيــه‬\n      ‫وكفــا عــن أذى املعصومــن )‪ .‬لــذا فقــد ثبــت لــدي ادانــة املدعــى عليــه‬\n\n‫‪317‬‬\n\f‫بقولــة للمدعــي ( يــا واطــي ) وحكمــت عليــه بجلــده خمــس جلــدات‬\n‫بحضــور املدعــي هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم‬\n‫علــى املدعــي قــرر قناعتــه كمــا قــرر املدعــى عليــه اعتراضــه بالئحــة‬\n‫اعتراضيــه فأفهمتــه بــأن لــه مــدة ثالثــن يومــا تبــدأ مــن هــذا اليــوم فــاذا‬\n‫مضــت املــدة ولــم يتقــدم املدعــي بشــيء فــأن احلكــم يكتســب القطعيــة‬\n‫ويســقط حقــه يف االعتــراض فجــرى تســليمه صــوره مــن صــك احلكــم‪.‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬هــ‪.‬‬\n‫ويف يــوم االثنــن املوافــق ‪ 1434/06/26‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 11:15‬وفيهــا قــد عــادت املعاملــة مــن محكمــة االســتئناف مصادقــا‬\n‫عليهــا بالقــرار رقــم ‪ 34235173‬وتاريــخ ‪1434/06/10‬هـ ـ وهــذا نصــه‬\n‫(وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم وبــاهلل‬\n‫التوفيــق) قاضــي اســتئناف ‪ ....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.....‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ....‬موقــع يف األصــل ومجــاز‪ .‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                         ‫حــرر يف ‪1434/6/26‬هــ‪.‬‬\n\n\n\n\n                                                                                        ‫‪318‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":316,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"44b263014403fd5e1dd9204acac77c0167434e2bd4d222f6e4ba82ff4eb4b1e9","normalized_text_hash":"0e89257f43166f052711e59d47763495f8a7753ba2ba0416200ddc32d4ebf8d8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p316-34175650"},{"id":"b91e364c-70f7-57cb-af41-dd084eb1fa55","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إيجابية التقرير الطبي للمدعي -إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","document_number":"3455790","case_number":"34107904","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/4","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إيجابية التقرير الطبي للمدعي -إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/3/4 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3455790 :‬‬\n                         ‫َر ْق ُم الدعوى‪34107904 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34167375‬تاريخه‪1434/03/21 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتســبب يف إصابــة ‪-‬‬\n      ‫مطالبــة املدعــي باملجــازاة ‪ -‬إيجابيــة التقريــر الطبــي للمدعــي ‪ -‬إقــرار‬\n                               ‫املدعــى عليــه بالدعــوى ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n                          ‫قول اهلل تعالى‪( :‬وال تعتدوا إن اهلل ال يحب املعتدين)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام باالعتــداء عليــه بالضــرب ممــا‬\n      ‫تســبب يف إصابتــه بكدمــات بالوجــه والركبتــن وســجحات بالظهــر‬\n      ‫وحتركــت بعــض أســنانه مــع نزيــف يســير بالفــم‪ ،‬ولــذا فقــد طلــب‬\n      ‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه مبــا جــاء‬\n      ‫يف الدعــوى جملــة وتفصيــا‪ -‬املدعــى عليــه أقــر بضــرب املدعــي وإحلــاق‬\n      ‫اإلصابــات املذكــورة بــه والشــرع قــد حــرم االعتــداء علــى اآلمنــن‬\n      ‫بغيــر حــق‪ -‬قضــت احملكمــة بســجن املدعــى عليــه عشــرة أيــام وجلــده‬\n      ‫خمســن جلــدة دفعــة واحــدة مــع أخــذ التعهــد عليــه بعــدم العــودة ملثــل‬\n      ‫ذلــك‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت‬\n                                    ‫محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n‫‪319‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34107904‬وتاريــخ‬\n‫‪1434/3/4‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34464667‬وتاريــخ‬\n‫‪1434/02/24‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/03/04‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر(‪ ).....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم(‪ ).....‬وادعــى علــى احلاضــر معــه يف مجلــس‬\n‫احلكــم (‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم(‪ ).....‬قائــا يف‬\n‫حتريــر دعــواه إنــه يف تاريــخ‪1433/06/03 :‬ه ـ ويف حــي (‪ ).....‬باملدينــة‬\n‫املنــورة قــام املدعــى عليــه باالعتــداء علــي وضربنــي بيــده علــى وجهــي‬\n‫وجنبــي عــدة ضربــات حتــى ســقطت علــى األرض وحلــق بــي كدمــات‬\n‫بالوجــه والركبتــن وســجحات بالظهــر وحتركــت بعــض أســناني مــع‬\n‫نزيــف يســير بالفــم مــن جــراء ذلــك وقــد صــدر بحقــي التقريــر الطبــي‬\n‫الصــادر مــن مستشــفى امليقــات باملدينــة املنــورة برقــم ‪23/1131/22‬‬\n‫يف ‪1433/6/3‬ه ـ وهــو متضمــن مــا ذكرتــه مــن اإلصابــات التــي حلقــت‬\n‫بــي ومــدة الشــفاء خمســة أيــام لــذا أطلــب احلكــم بتأديــب املدعــى عليــه‬\n‫لقــاء اعتدائــه وإحلــاق اإلصابــات بــي هــذه دعــواي وبســؤال املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي يف دعــواه‬ ‫عمــا جــاء يف دعــوى املدعــي أجــاب قائ ـ ً‬\n‫صحيــح ففــي التاريــخ املذكــور يف الدعــوى وقــع بينــي وبــن املدعــي‬\n‫مشــادة كالميــة متاســكنا باأليــدي وقــد ضربتــه بيــدي علــى وجهــه‬\n‫وجنبيــه فســقط علــى األرض مــن جــراء ذلــك وحلقــه اإلصابــات املبينــة‬\n\n                                                                                        ‫‪320‬‬\n\f      ‫يف دعــواه وهــي منــي دون غيــري وقــد حكــم علــي يف احلــق العــام باجللــد‬\n      ‫والســجن هكــذا أجــاب هــذا وقــد جــرى اإلطــاع علــى التقريــر الطبــي‬\n      ‫املرفــق باملعاملــة و الصــادر مــن مستشــفى امليقــات باملدينــة املنــورة برقــم‬\n      ‫‪ 23/1131/22‬يف ‪1433/06/03‬ه ـ املتضمــن إصابــة املدعــي بكدمــة‬\n      ‫بالوجه وأخرى بالركبة اليمنى وسجحات بالظهر وحترك يف األسنان‬\n      ‫ونزيــف يســير بالفــم ومــدة الشــفاء خمســة أيــام كمــا جــرى اإلطــاع‬\n      ‫علــى القــرار الشــرعي الصــادر منــي يف احلــق العــام برقــم ‪ 33446254‬يف‬\n      ‫‪1433/11/03‬ه ـ واملصــدق مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫والقاضــي بجلــد املدعــى عليــه خمســن جلــدة وســجنه عشــرة أيــام‬\n      ‫وأخــذ التعهــد عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا‬\n      ‫أن املدعــى عليــه صــادق علــى دعــوى املدعــي فأقــر باالعتــداء وضــرب‬\n      ‫املدعــي وإحلــاق اإلصابــات بــه املذكــورة آنف ـ ًا ومبــا أن الشــرع قــد حــرم‬\n      ‫االعتــداء علــى اآلمنــن بغيــر حــق فقــال ســبحانه (وال تعتــدوا إن اهلل‬\n      ‫ال يحــب املعتديــن) ومبــا أن التعزيــر يشــرع يف كل معصيــة ال حــد‬\n      ‫فيهــا وال كفــارة جلميــع مــا ذكــر فقــد حكمــت بتعزيــر املدعــى عليــه‬\n      ‫للحــق اخلــاص وذلــك بجلــده خمســن جلــدة تقــع علــى بدنــه دفعــة واحــدة‬\n      ‫ويســجن عشــرة أيــام كاملــة ويؤخــذ عليــه التعهــد بعــد م العــودة ملثــل‬\n      ‫ذلــك وبعرضــه قــرر املدعــي قناعتــه باحلكــم أمــا املدعــى عليــه فقــرر‬\n      ‫عــدم قناعتــه باحلكــم وطلــب رفعــه إلــى محكمــة االســتئناف بــدون‬\n      ‫الئحــة اعتراضيــة فأجيــب لطلبــه وقــد انتهــت اجللســة يف متــام الســاعة ‪20‬‬\n      ‫‪ 10 :‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                    ‫وســلم ‪ .‬حــرر يف ‪1434/3/4‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪ -:‬فقــد‬\n\n\n‫‪321‬‬\n\f‫جــرى منــا نحــن قضــاة الدائــرة اجلزائية الســابعة يف محكمة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34464667‬وتاريــخ‬\n‫‪1434/3/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪).....( /‬‬\n‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 3455790‬وتاريــخ‬\n‫‪1434/3/4‬ه ـ احملكــوم فيــه مبــا دون بباطــن القــرار ‪ ،‬املتضمــن دعــوى‬\n‫املدعــي العــام ضــد احلــدث‪ ( ).....( /‬العمــر‪ 16‬ســعودي اجلنســية ) املتهــم‬\n‫يف مضاربــة ‪ ،‬وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى‬\n‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                       ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪322‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":319,"source_page_end":322,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"64749e550bcb6fd1248ca31a730c7b98d3db954a9d4150df8ada41b555b288d1","normalized_text_hash":"7b9644e01509f431d160480317e00f6961f0dd08ce65e797b06928131e31b2f4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p319-3455790"},{"id":"43e22a1a-8cd7-5a19-82c7-7d441045fb6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب واللعن -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز عن إقامة البينة- مين على نفي الدعوى -رد الدعوى.","document_number":"34219039","case_number":"34149417","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/21","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب واللعن -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز عن إقامة البينة- مين على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34219039 :‬‬\n                         ‫َر ْق ُم الدعوى‪34149417 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34274125‬تاريخه‪1434/07 /19 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب واللعــن ‪ -‬مطالبــة املدعــي‬\n      ‫باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬عجــز عــن إقامــة البينــة‪-‬‬\n                                       ‫ميــن علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬لــو يعطــى النــاس بدعواهــم الدعــى‬\n                ‫نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بســبه ولعــن والديــه كمــا أنــه قــام‬\n      ‫مبضايقتــه ومطاردتــه بالســيارة‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫لقــاء ذلــك ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي جملــة‬\n      ‫وتفصيــا ‪ -‬املدعــي ليــس لديــه بينــة تثبــت دعــواه وطلــب ميــن املدعــى‬\n      ‫عليــه علــى نفيهــا فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بعــدم‬\n      ‫اســتحقاق املدعــي ملــا يدعيــه لعــدم ثبــوت دعــواه‪ -‬قنــع املدعــى عليــه‬\n      ‫باحلكــم وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                           ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫‪323‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة اجلزائيــة يف‬\n‫محافظــة األحســاء املكلــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم‬\n‫‪ 34149417‬وتاريــخ ‪ 1434/04/01‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 34794771‬وتاريــخ ‪1434/4/1‬ه ـ حضــر‪ ......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ......‬وادعــى ضــد ‪ ......‬ســعودي اجلنســية مبوجــب‬\n‫ا لقــد ســبق وان قــام هــذا احلاضــر معــي‬   ‫الســجل املدنــي رقــم ‪ ......‬قائ ـ ً‬\n‫مبضايقتــي ومطاردتــي بالســيارة كمــا انــه قــام بســبي ولعــن والــدي‬\n‫اطلــب مجازاتــه لقــاء ذلــك علمــا بــأن شــقيقي متــزوج بابنــة أخ املدعــى‬\n‫عليــه وتوجــد بينهمــا عــداوة وقــد حلقنــي بتلــك العــداوة وبعــرض تلــك‬\n‫الدعــوى علــى املدعــى عليــه أجــاب قائــا ال صحــة ملــا ذكــره املدعــي‬\n‫مــن مضايقتــي لــه ومطاردتــي لــه بالســيارة كمــا ال صحــة ملــا ذكــره‬\n‫املدعــي مــن قيامــي بســبه ولعــن والــده لــذا فليــس لــه حــق عنــدي وبــرد‬\n‫ذلــك علــى املدعــي قــال الصحيــح هــو مــا ذكرتــه يف دعــواي وليــس‬\n‫لــدي بينــه واطلــب ميينــه علــى نفــي دعــواي فــان هــو حلــف فــا أطالبــه‬\n‫بشــي بخصــوص هــذه الدعــوى وبعــرض ذلــك علــى املدعــى عليــه اســتعد‬\n‫بــأداء اليمــن وأداهــا قائــا واهلل العظيــم أننــي لــم أضايــق ‪ ......‬هــذا‬\n‫احلاضــر معــي ولــم أطــارده بالســيارة ولــم أقــم بســبه ولعــن والــده لــذا‬\n‫وبعــد ســماع الدعــوى واإلجابــة وحيــث طلــب املدعــي مجــازاة املدعــى‬\n‫عليــه لقــاء مضايقتــي لــه ومطاردتــي لــه بالســيارة وقيامــه بســبه ولعــن‬\n‫والــده وإن املدعــى عليــه قــد انكــر ذلــك وإنــه ال بينــة لــدى املدعــي علــى‬\n‫دعــواه وإن املدعــي قــد طلــب ميــن خصمــه علــى نفــي دعــواه وإن املدعــى‬\n\n                                                                                       ‫‪324‬‬\n\f      ‫عليــه قــد اســتعد بــأداء اليمــن وأداهــا ولقولــه عليــه الصــاة والســام‬\n      ‫(لــو يعطــى النــاس بدعواهــم الدعــى أنــاس دمــاء رجــال وأموالهــم ولكــن‬\n      ‫اليمــن علــى املدعــى عليــه ) وملــا هــو مقــرر شــرع ًا مــن أن اليمــن تقطــع‬\n      ‫اخلصومــة يف احلــال لــذا فقــد حكمــت بعــدم اســتحقاق املدعــي ‪......‬‬\n      ‫لدعــواه ضــد ‪ ......‬لعــدم ثبوتهــا وبذلــك حكمــت وبعرضــه قــرر املدعــي‬\n      ‫عــدم قناعتــه بــه وطلــب تقــدمي الئحــة اعتراضيــة فجــرى إفهامــه بأنــه‬\n      ‫ســوف يتــم تســليمه صــورة مــن القــرار الشــرعي هــذا اليــوم وإن لــه مــدة‬\n      ‫ثالثــن يوم ـ ًا تبــدأ مــن تاريــخ اســتالمه بعدهــا يســقط حقــه يف تقــدمي‬\n      ‫الالئحــة أمــا املدعــى عليــه فقــرر قناعتــه بــه وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n      ‫الشــيخ‪ ......‬برقــم ‪ 34/794771‬وتاريــخ ‪1434/7/3‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلته املســجل برقــم ‪ 34219039‬وتاريــخ ‪1434/5/21‬هـ‬\n      ‫اخلــاص بدعــوى ‪ ......‬ضــد ‪ ......‬يف قضيــة ســب أو شــتم وقــد تضمن القرار‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكم واهلل املوفق وصلى‬\n       ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪14347/7/18‬هــ‪.‬‬\n\n\n\n\n‫‪325‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":323,"source_page_end":325,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ea5ec760788dbe00ba537fefc4651a8072d3066596eb008ef196afe87a3d0bc","normalized_text_hash":"87338e19764b9839441b9d5c08f1a9d1e3b3af9a37942c4432bcb929139e43fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p323-34219039"},{"id":"3fd49eca-2447-5ef9-b635-b4b16138e7bb","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب واتهام الشرف -مطالبة املدعية باملجازاة -إنكار املدعي عليه الدعوى -افتقاد املدعية البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34259492","case_number":"34176629","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/4","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب واتهام الشرف -مطالبة املدعية باملجازاة -إنكار املدعي عليه الدعوى -افتقاد املدعية البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1433/7/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34259492 :‬‬\n                   ‫َر ْق ُم الدعوى‪34176629 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34300798‬تاريخه‪1434/8/21 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب واتهــام الشــرف ‪ -‬مطالبــة‬\n‫املدعيــة باملجــازاة ‪ -‬إنــكار املدعــي عليــه الدعــوى ‪ -‬افتقــاد املدعيــة‬\n       ‫البينــة ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                  ‫مــن أنكــر)‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليــه قــام بالتلفــظ عليهــا وذلــك باتهــام‬\n‫شــرفها حيــث ذكــر أن أحــد األشــخاص يكثــر دخولــه وخروجــه إلــى‬\n‫شــقتها وأن هنــاك ســيارات مختلفــة تركــب معهــا كمــا أنــه ينظــر إليهــا‬\n‫بحــدة وال يغــض بصــره عنهــا‪ ،‬ولــذا فقــد طلبــت احلكــم عليــه بعقوبــة‬\n‫تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعيــة‬\n‫جملــة وتفصيــا‪ -‬طلبــت احملكمــة مــن املدعيــة أن تقــدم بينتهــا علــى‬\n‫دعواهــا فعجــزت عــن ذلــك وطلبــت ميــن املدعــى عليــه علــى نفيهــا فأداها‬\n‫طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى‬\n‫املدعيــة‪ -‬عارضــت املدعيــة علــى احلكــم‪ -‬قــررت محكمــة االســتئناف‬\n                                          ‫باألكثريــة املوافقــة علــى احلكــم‪.‬‬\n\n                                                                                  ‫‪326‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34176629‬وتاريــخ‬\n      ‫‪ 1434/4/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34942251‬وتاريــخ‬\n      ‫‪1434/4/16‬ه ففــي يــوم الثالثــاء املوافق‪1434/06/20‬ه ـ افتتحــت‬\n      ‫اجللســة وفيهــا حضــرت املدعيــة ‪ ....‬ســعودية بالســجل املدنــي رقــم‪.....‬‬\n      ‫واملعــرف بهــا مــن قبــل ابنهــا (‪ ).....‬ســعودي بالســجل املدنــي رقــم (‪).....‬‬\n      ‫وحضــر املدعــى عليــه (‪ ).....‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬وادعــت‬\n      ‫املدعيــة قائل ـ ًة إن املدعــى عليــه يســكن يف إحــدى شــقق العمــارة التــي‬\n      ‫أســكن فيهــا وقــد اعتــدى علــى خصوصيتــي واتهــم شــريف حيــث ذكــر‬\n      ‫أن أحــد األشــخاص ويعمــل مدرس ـ ًا كثــر دخولــه وخروجــه لشــقتي‬\n      ‫وهنــاك ســيارات أشــكال وألــوان أركــب معهــا وبلــغ أحــد ســكان‬\n      ‫العمــارة أنــه ســيقوم بإبــاغ الهيئــة عنــي كمــا أنــه ينظــر إلــي بحــدة وال‬\n      ‫يغــض بصــره وقلــت لــه غــض البصــر فقــال أبنظــر إليــك أطلــب إثبــات‬\n      ‫إدانتــه بذلــك وتعزيــره هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫ا مــا ذكرتــه املدعيــة غيــر صحيــح ســوى أنــي ســألت وهــو‬    ‫أجــاب قائ ـ ً‬\n      ‫أحــد ســكان العمــارة عــن رجــل يدخــل ويخــرج يف العمــارة فقــال لــي‬\n      ‫إن هــذا مــدرس خصوصــي يأتــي ليــدرس أبنــاء املدعيــة هــذه إجابتــي‬\n      ‫وبســؤال املدعيــة هــل لديــك بينــة علــى ذلــك فقالــت نعــم وأطلــب مهلــة‬\n      ‫إلحضارهــا هكــذا أجابــت وعليــه رفعــت اجللســة لذلــك ويف يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/07/04‬ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعيــة‬\n\n‫‪327‬‬\n\f‫واملعــرف بهــا مــن قبــل ابنهــا وبســؤالها عــن بينتهــا فقالــت طلبــت مــن‬\n‫الشــاهد احلضــور ورفــض أطلــب ميــن املدعــى عليــه علــى نفــي دعــواي‬\n‫هــذه إجابتــي وبعــرض ذلــك علــى املدعــى عليــه قــال مســتعد ببــذل اليمــن‬\n‫ا بعــد إذنــي لــه وبعــد تخويفــه مبــآالت اليمــن الكاذبــة‬       ‫فحلــف قائ ـ ً‬\n‫(واهلل الــذي ال إلــه إال هــو الــذي يعلــم الســر وأخفــى أنــي غــاض بصــري‬\n‫عــن ولــم أتهمهــا بشــرفها هكــذا أحلــف ) فبنــاء علــى مــا ســلف مــن‬\n‫الدعــوى واإلجابــة وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا محضــر‬\n‫االســتدالل الصــادر مــن شــرطة التنعيــم مبكــة ونظــرا إلنــكار املدعــى‬\n‫عليــه دعــوى املدعيــة ولعــدم تقــدمي املدعيــة بينــة علــى دعواهــا ولطلبهــا‬\n‫ميــن املدعــى عليــه وحللــف املدعــى عليــه علــى نفــي دعــوى املدعيــة ولقولــه‬\n‫صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن أنكــر) ملــا‬\n‫ســبق كلــه فقــد صرفــت النظــر عــن دعــوى املدعيــة وبعــرض ذلــك عليهــا‬\n‫قــررت االعتــراض بالئحــة وجــرى تســليمها صــورة مــن القــرار الشــرعي‬\n‫وأفهمــت بنظــام االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/4‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم (‪ )34942251‬وتاريخ‬\n‫‪1434/8/9‬ه املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪).....(/‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة برقــم (‪)34259492‬‬\n‫وتاريــخ ‪1434/7/4‬ه املتضمــن دعــوى املدعيــة (‪ ).....‬ســعودية اجلنســية‬\n‫ضــد (‪ ).....‬ســعودي اجلنســية بشــأن ســب وشــتم‪ ،‬احملكــوم فيــه مبــا دون‬\n\n\n                                                                                      ‫‪328‬‬\n\f      ‫بباطــن القــرار‪ ،‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫قررنــا باألكثريــة املوافقــة علــى احلكــم‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل‬\n                                  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":326,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cf2b72f29817e4113e24da8d4b46d13f0a0a5dba3efe2f862d35038e75bb46fc","normalized_text_hash":"7bd04e4e06234e9ebb25b6bdcdfa6bdace5649780f164df5ced4ce2320103e0c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p326-34259492"},{"id":"80294ed8-f57d-5fe5-b6df-5078d21fdcb3","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ أمام مجلس القضاء -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -رد شهادة الوكيل ملوكله فيما هو وكيل فيه -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34248488","case_number":"34221527","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/21","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ أمام مجلس القضاء -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -رد شهادة الوكيل ملوكله فيما هو وكيل فيه -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/21 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34248488 :‬‬\n                   ‫َر ْق ُم الدعوى‪34221527 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34296772‬تاريخه‪1434/8 /14 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والتلفــظ أمــام مجلــس‬\n‫القضــاء ‪ -‬مطالبــة املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى‬\n‫‪ -‬بينــة املدعــي غيــر موصلــة‪ -‬رد شــهادة الوكيــل ملوكلــه فيمــا هــو‬\n‫وكيــل فيــه‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n                      ‫‪ -1‬قول اهلل تعالى‪(( :‬وأشهدوا ذوي عدل منكم ))‪.‬‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                           ‫علــى مــن أنكــر)‪.‬‬\n‫‪ -3‬قــول ابــن قدامــة رحمــه اهلل يف املغنــي (‪« :)258/7‬وال تقبــل شــهادته‬\n               ‫لــه‪-‬أي الوكيــل ملوكلــه‪ -‬فيمــا هــو وكيــل فيــه ‪..‬إلــخ»‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه قــام بســبه والتلفــظ عليــه مبــا جــاء يف‬\n‫دعــواه وذلــك أثنــاء ترافعهمــا أمــام إحــدى احملاكــم‪ ،‬وطلــب احلكــم‬\n‫عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف‬\n‫دعــوى املدعــي ســوى أنــه أثنــاء نظــر قضيــة حضانــة أقامهــا املدعــي‬\n‫ا عــن ابنتــه‪ :‬هــل املدعــي أهــل للحضانــة؟‬  ‫ســأله القاضــي بصفتــه وكيـ ً‬\n‫ا للحضانــة فهــو متهــاون يف الصــاة وكثيــر‬        ‫فأجــاب بأنــه ليــس أه ـ ً‬\n\n                                                                                     ‫‪330‬‬\n\f      ‫الســفر‪ -‬طلبــت احملكمــة مــن املدعــي أن يقــدم بينتــه علــى دعــواه‬\n      ‫فأحضــر شــاهدين إال أن احملكمــة قــررت رد شــهادة األول منهمــا‬\n      ‫ألنــه وكيــل للمدعــي يف كال القضيتــن ورد شــهادة الثانــي ألنــه عجــز‬\n      ‫عــن إحضــار معدلــن لــه‪ -‬طلــب املدعــي ميــن املدعــى عليــه علــى نفــي‬\n      ‫دعــواه فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بعــدم ثبــوت دعــوى‬\n      ‫املدعــي جتــاه املدعــى عليــه‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n             ‫املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا (‪ ).....‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر‬\n      ‫برقــم ‪ 34221527‬وتاريــخ ‪1434/05/13‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 341177869‬وتاريــخ ‪1434/05/13‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافق‪1434/06/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر‬\n      ‫‪ ....‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬وادعــى علــى احلاضــر ‪ ....‬ســعودي‬\n      ‫ال يف دعواه إن املدعى عليه والد طليقتي‬           ‫بالســجل املدني رقم (‪ ).....‬قائ ً‬\n      ‫وهــو خالــي شــقيق والدتــي وقــد أقمــت دعــوى يف احملكمــة العامــة ضــد‬\n      ‫طليقتــي بطلــب حضانــة ابنتــي وعمرهــا ثــاث ســنوات وكان موعــد‬\n      ‫اجللسة هو ‪1434/5/12‬هـ لدى القاضي باحملكمة العامة باخلبر (‪).....‬‬\n      ‫ا عــن ابنتــه وقــد قــال املدعــى عليــه عنــي‬\n                                                     ‫وقــد حضــر املدعــى عليــه وكيـ ً‬\n      ‫يف مجلــس القضــاء بأنــي ســكير نكيــر راعــي دســكوات ومراقــص‬\n      ‫ـاء عليــه أطلــب تأديبــه لقــاء ســبه وشــتمه لــي‬  ‫وغيــر صالــح للتربيــة وبنـ ً‬\n‫‪331‬‬\n\f‫بهــذا الــكالم هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب‬\n‫بقولــه إن املدعــي ابــن شــقيقتي وقــد تــزوج ابنتــي قبــل خمــس ســنوات‬\n‫تقريبـ ًا وحصــل الطــاق بينهمــا قبــل ســنتني تقريبـ ًا وبينهمــا بنــت اســمها‬\n‫(‪ ).....‬عمرهــا ثــاث ســنوات وهــي لــدى والدتهــا ابنتــي وقــد أقــام املدعــي‬\n‫ا عــن ابنتــي‬‫دعــوى ضــد ابنتــي يطلــب حضانــة ابنتهمــا فحضــرت وكيـ ً‬\n‫يف تاريــخ ‪1434/5/12‬ه ـ لــدى القاضــي يف احملكمــة العامــة باخلبــر‬\n‫(‪ ).....‬وقــد ســألني القاضــي هــل املدعــي أهــل للحضانــة فقلــت إنــه ليــس‬\n‫ا للحضانــة فهــو متهــاون يف الصــاة وكثيــر الســفر هــذا مــا قلتــه‬       ‫أه ـ ً‬\n‫ال متهــاون يف الصالة وكثير‬        ‫فقــط بعــد ســؤال القاضــي لــي واملدعــي فع ً‬\n‫الســفر وهــو يعلــم ذلــك هكــذا أجــاب وبعــرض ذلــك علــى املدعــي قــال‬\n‫نعــم أنــا كثيــر الســفر لــ‪ .........‬لكــن معظــم ســفري لــ‪ .........‬مــع أهلــي‬\n‫وأحيان ـ ًا أســافر لوحــدي وأحيان ـ ًا مــع بعــض الشــباب وأحضــر قاعــات‬\n‫الســينما وأشــاهد األفــام فيهــا أفــام حركيــة ورومانســية وحــروب‬\n‫وأمــا الصــاة فصــاة الفجــر أصليهــا إذا اســتيقظت للــدوام ويف هــذه‬\n‫األيــام أصليهــا عنــد الســابعة إال ربــع بعــد خــروج وقتهــا وذلــك ألنــي ال‬\n‫أســتيقظ للــدوام إال يف هــذا الوقــت وباقــي الصلــوات أصليهــا يف وقتهــا‬\n‫يف املســجد وأمــا مــا ذكــره املدعــي مــن أنــه لــم يتلفــظ باأللفــاظ التــي‬\n‫ذكرتهــا يف دعــواي فغيــر صحيــح ولــدي شــاهدين علــى صحــة كالمــي‬\n‫وهمــا حاضريــن معــي وأطلــب ســماع شــهادتهما ثــم حضــر (‪ ).....‬ســعودي‬\n‫بالســجل املدنــي رقــم (‪ ).....‬وبســؤاله عمــا لديــه مــن شــهادة قــال إنــي‬\n‫اعمــل يف مكتــب القاضــي يف احملكمــة العامــة باخلبــر (‪ ).....‬ويف شــهر‬\n‫جمــادى األولــى ال أذكــر التاريــخ كان هنــاك جلســة لــدى الشــيخ‬\n‫ا عــن ابنتــه يف‬‫وطــريف الدعــوى همــا املدعــي واملدعــى عليــه (‪ ).....‬وكيـ ً‬\n\n\n                                                                                       ‫‪332‬‬\n\f      ‫قضيــة حضانــة وكنــت متواجــد ًا يف املكتب وســمعت الشــيخ يســأل هل‬\n      ‫ا حلضانــة البنــت فقــال املدعــى عليــه راعــي بحريــن هــذا مــا‬ ‫املدعــي أهـ ً‬\n      ‫لــدي مــن شــهادة كمــا (‪).....‬حضــر ســعودي بالســجل املدنــي رقــم (‪).....‬‬\n      ‫وبســؤاله عمــا لديــه مــن شــهادة قــال إنــي وكيــل للمدعــي وقــد أقــام‬\n      ‫دعــوى يف احملكمــة العامــة ضــد طليقتــه بشــأن حضانــة ابنتهــا وقــد‬\n      ‫وكلنــي يف الترافــع بالدعــوى وحضرنــا لــدى الشــيخ وقــد ســأل الشــيخ‬\n      ‫ا للحضانــة فقــال إنــه ســكير نكيــر‬        ‫املدعــى عليــه هــل املدعــى أه ـ ً‬\n      ‫راعــي بنــات راعــي مراقــص وبــ‪ ........‬هــذا مــا لــدي مــن شــهادة هكــذا‬\n      ‫شــهدا وبســؤال املدعــي ألديــك زيــادة بينــة فقــال ال يوجــد لــدي شــهود‬\n      ‫غيــر هذيــن الشــاهدين وبعــرض الشــاهدين وشــهادتهما علــى املدعــى‬\n      ‫عليــه قــال أمــا الشــاهد األول فــا أعلــم عــن حالــه وقــد يكــون بينــه‬\n      ‫وبــن املدعــي (‪ ).....‬عالقــة وشــهادته غيــر صحيحــة وال أقبــل بهــا وأمــا‬\n      ‫الشــاهد فهــو وكيــل املدعــي يف القضيــة املقامــة يف احملكمــة العامــة‬\n      ‫وكذلــك وكيلــه يف هــذه القضيــة فهــو مــن أقــام الدعــوى عنــه وكتــب‬\n      ‫صحيفــة الدعــوى فهــذه الشــهادة فيهــا مصلحــة لــه فهــو يهمــه كســب‬\n      ‫القضيــة للفائــدة املاديــة واملعنويــة وشــهادته غيــر صحيحــة وال أقبــل بهــا‬\n      ‫هكــذا قــرر وبعــرض ذلــك علــى الشــاهدين قال الشــاهد ال يوجد لي أي‬\n      ‫عالقــة باملدعــي وقــال الشــاهد نعــم أنــا وكيــل للمدعــي (‪ ).....‬يف هــذه‬\n      ‫القضيــة وقــد قــام موظــف مكتبــي بكتابــة صحيفــة الدعــوى والتقــدم‬\n      ‫بهــا للترافــع عنــه وكذلــك وكيلــه يف القضيــة املنظــورة لــدى الشــيخ‬\n      ‫هكــذا قــرر وبطلــب معدلــن للشــاهد (‪ ).....‬قــال الشــاهد (‪ ).....‬أنــا ال‬\n      ‫أســتطيع إحضــار معدلــن لــي ولــن أحضرهــم هكــذا قــرر ثــم أقفلــت‬\n      ‫اجللســة الســاعة العاشــرة للتأمــل وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n\n\n‫‪333‬‬\n\f‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم األربعــاء ‪1434/6/21‬ه ـ‬\n‫الســاعة الثامنــة والنصــف افتتحــت اجللســة بحضــور املدعــي واملدعــى‬\n‫عليــه وجــرى افهــام املدعــي بــأن لــه ميــن املدعــى عليــه (‪ ).....‬علــى نفــي‬\n‫دعــواه فقــال أنــا أطلبهــا وأقبــل بهــا وبعــرض اليمــن علــى املدعــى عليــه‬\n‫ا واهلل العظيــم أنــي لــم أقــل عــن‬‫اســتعد بهــا ثــم أذنــت لــه فحلــف قائ ـ ً‬\n‫املدعــي أنــه ســكير نكيــر راعــي دســكوات ومراقــص وغيــر صالــح‬\n‫للتربيــة وذلــك اثنــاء نظــر الدعــوى لــدى القاضــي يف احملكمــة العامــة‬\n‫ـاء علــى مــا تقــدم مــن‬‫باخلبــر الشــيخ واهلل العظيــم هكــذا حلــف فبنـ ً‬\n‫الدعــوى واإلجابــة وحيــث أنكــر املدعــى عليــه الدعــوى وال بينــة مثبتــة‬\n‫للمدعــي علــى دعــواه وأمــا الشــاهد فقــد قــرر بأنــه ال يســتطيع احضــار‬\n‫معدلــن وقــد قــرر العلمــاء رحمهــم اهلل تعالــى بــأن مــن شــروط الشــاهد‬\n‫العدالــة لقــول اهلل تعالى((وأشــهدوا ذوي عــدل منكــم ))وأمــا الشــاهد‬\n‫فهــو وكيــل للمدعــي وهــو مــن كان يترافــع عنــه لــدى الشــيخ ويدعــي‬\n‫بــأن املدعــى عليــه صــدرت منــه األلفــاظ محــل الدعــوى وهــو كذلــك‬\n‫مــن كتــب صحيفــة الدعــوى يف هــذه القضيــة فهــو يف احلقيقــة خصــم‬\n‫للمدعــى عليــه قــال ابــن قدامــه رحمــه اهلل يف املغنــي(‪(( :)258/7‬وال‬\n‫تقبــل شــهادته لــه‪-‬أي الوكيــل ملوكلــه‪ -‬فيمــا هــو وكيــل فيــه ألنــه‬\n‫يثبــت لنفســه حقــا بدليــل أنــه إذا وكلــه يف قبــض حــق فشــهد بــه لــه ثبــت‬\n‫اســتحقاق قبضــه وألنــه خصــم فيــه بدليــل أنــه ميلــك املخاصمــة فيــه))‪.‬‬\n‫وحيــث حلــف املدعــى عليــه علــى نفــي الدعــوى ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم((البينة علــى املدعــي واليمــن علــى مــن أنكــر)) لــذا‬\n‫فقــد حكمــت بعــدم ثبــوت دعــوى املدعــي جتــاه املدعــى عليــه وبعــرض‬\n‫احلكــم علــى الطرفــن قنــع املدعــى عليــه ولــم يقنــع املدعــي واســتعد‬\n\n\n                                                                                      ‫‪334‬‬\n\f      ‫بتقــدمي الئحــة اعتراضيــة فأفهــم مبراجعــة احملكمــة يــوم الســبت‬\n      ‫‪1434/6/24‬ه ـ الســتالم صــورة احلكــم وتقــدمي اعتراضــه خــال ثالثني‬\n      ‫يوم ـ ًا إن لــم يقدمــه ســقط حقــه يف االعتــراض كمــا قــررت الكتابــة‬\n      ‫لدائــرة التحقيــق واالدعــاء العــام إلكمــال الــازم حيــال املدعــي لتهاونــه‬\n      ‫يف صــاة الفجــر وأقفلــت اجللســة الســاعة التاســعة وصلــى اهلل وســلم‬\n                                                                  ‫علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم االربعــاء ‪1434/7/26‬ه ـ‬\n      ‫الســاعة الثانيــة عشــر والنصــف افتتحــت اجللســة وقــد انتهــت املــدة‬\n      ‫النظاميــة لالعتــراض ولــم يقــدم املدعــي الئحتــه االعتراضيــة لــذا فقــد‬\n      ‫ســقط حقــه يف االعتــراض وقــررت إحالــة املعاملــة حملكمــة االســتئناف‬\n                         ‫لتدقيــق احلكــم وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n      ‫‪ 34/1177869‬وتاريــخ ‪1434/7/29‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 341892585‬وتاريــخ ‪1434/8/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪34248488‬‬\n      ‫وتاريــخ ‪1434/6/21‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‪ ).....(/‬يف قضيــة‬\n      ‫قــذف وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                               ‫يف ‪1434/8/13‬هــ‪.‬‬\n\n\n\n‫‪335‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":330,"source_page_end":335,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"27397edd83202ea6ee00292cebbb93c1ecc692c9bed7c8c90f155f40c4fb2593","normalized_text_hash":"bfcd90a573e2750c747d55b18d10ee605de122b12aec76dc90c0a15a537a14c9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p330-34248488"},{"id":"175d99c0-d98f-5f44-8ef5-1bcc5c2b9f49","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعى غير موصلة -رد شهادة -مين املدعى عليه على نفي الدعوى -رد","document_number":"34281307","case_number":"34228115","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة يف شأن مالي ويف المحكمة اجلزائية يف سب وشتم تلفظ به الشاهد على موكلي و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/26","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعى غير موصلة -رد شهادة -مين املدعى عليه على نفي الدعوى -رد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34281307 :‬‬\n                   ‫َر ْق ُم الدعوى‪34228115 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34380493‬تاريخه‪1434/12/18 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص) ‪ -‬اعتــداء بالقــذف والســب والشــتم ‪-‬‬\n‫مطالبــة املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــى‬\n‫غيــر موصلــة ‪ -‬رد شــهادة ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى ‪ -‬رد‬\n                                                                        ‫الدعــوى‪.‬‬\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه قــام بقــذف موكلتــه ووصفهــا‬\n‫بالــكالم البــذيء املذكــور يف دعــواه‪ ،‬وطلــب احلكــم عليــه بحــد‬\n‫القــذف لقــاء ذلــك‪ -‬أنكــر وكيــل املدعــى عليــه مــا جــاء يف دعــوى‬\n‫املدعــي جملــة وتفصيــا‪ -‬طلبــت احملكمــة مــن وكيــل املدعيــة أن‬\n‫يقــدم بينتــه علــى دعــواه فأحضــر شــاهد ًا واحــد ًا إال أن احملكمــة قــررت‬\n‫رد شــهادته لظهــور تربصــه باملدعــى عليــه‪ ،‬كمــا قــدم تســجيال صوتيـ ًا‬\n‫لــم يثبــت أنــه بصــوت املدعــى عليــه‪ ،‬ومــؤدى ذلــك أن بينتــه غيــر موصلــة‬\n‫إلثبــات دعــواه ‪-‬طلــب وكيــل املدعيــة ميــن املدعــى عليــه على نفــي دعواه‬\n‫فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بصــرف النظر عــن دعوى‬\n\n\n                                                                                     ‫‪336‬‬\n\f      ‫املدعيــة وأخلــت ســبيل املدعــى عليــه منهــا‪ -‬عــارض وكيــل املدعيــة علــى‬\n                 ‫احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬مســاعد رئيــس احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34228115‬وتاريــخ‬\n      ‫‪1434/5/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341208414‬وتاريــخ‬\n      ‫‪1434/5/18‬ه ـ ففــي يــوم الســبت املوافــق ‪1434/6/3‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة (‪ )10:30‬للنظــر يف دعــوى املدعيــة وفيهــا حضــر املدعــي‬\n      ‫وكالــة ‪ .....‬بالســجل املدنــي رقــم (‪ ).....‬وأدعــى علــى ‪ ....‬بالســجل املدنــي‬\n      ‫رقــم (‪ ).....‬بالوكالــة عــن (‪ ).....‬ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫ا يف دعــواه عليــه قــام املدعــى عليــه أصالــة بالتلفــظ علــى‬      ‫(‪ ).....‬قائ ـ ً‬\n      ‫والدتــي باأللفــاظ التاليــة (مهــي كويســه وأنهــا كانــت تتكلــم معــاه‬\n      ‫يف أمــور مــا هــي كويســه ) (احلرمــة كانــت نيتهــا خبيثــة واآلدميــة فيهــا‬\n      ‫حاجــه غلــط وأنــه كان يجبلهــا الهدايــا) (‪( ).....‬أن املدعــى عليــه كان‬\n      ‫جالــس مــع يف بيتهــم وكانــت البســه شرشــف صــاة وقامــت وضمتــه‬\n      ‫قــدام عيالهــا) وتفــوه بهــذه األلفــاظ يف منتــزه ‪ .......‬بطريــق مكــة جــدة‬\n      ‫يف ‪2012/10/14‬م أطلــب احلكــم عليــه بإقامــة حــد القــذف بحقــه‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه وكالــة قــال مــا ادعــاه املدعــي غيــر‬\n      ‫ا وبطلــب البينــة مــن املدعــي أحضــر للشــهادة‬      ‫صحيــح جمل ـ ًة وتفصي ـ ً‬\n      ‫وأدائهــا ‪ .........‬بالســجل املدنــي رقــم (‪ ).....‬املولــود يف ‪1402/1/15‬ه ـ‬\n      ‫وبســؤاله عــن مقــر ســكنه وعالقتــه باملدعيــة قــال أســكن يف مكــة‬\n\n‫‪337‬‬\n\f‫ا كنــت يف‬     ‫وال تربطنــي باملدعيــة أي عالقــة وباستشــهاده شــهد هلل قائـ ً‬\n‫منتــزه ‪ ......‬يف طريــق مكــة جــدة مــع املدعــى عليــه أصالــة وكنــت قــد‬\n‫أعــددت جهــاز جوالــي علــى خاصيــة التســجيل لســبق صــدور الــكالم‬\n‫البــذيء مــن املدعــى عليــه وقــد كان بينــي وبينــه نقــاش حــول بعــض‬\n‫املشــاكل بــن املدعيــة واملدعــى عليــه وقــد ســمعته يقــول عــن املدعيــة‬\n‫(مهــي كويســه وأنهــا كانــت تتكلــم معــاه يف أمــور مــا هــي كويســه‬\n‫) (احلرمــة كانــت نيتهــا خبيثــة واآلدميــة فيهــا حاجــه غلــط وأنــه كان‬\n‫يجبلهــا الهدايــا) (‪( ).....‬أن املدعــى عليــه كان جالــس مــع (‪ ).....‬يف‬\n‫بيتهــم وكانــت البســه شرشــف صــاة وقامــت وضمتــه قــدام عيالهــا)‬\n‫ا للمدعــى عليــه وقــد ســحب منــي‬        ‫ا وأنــا كنــت وكي ـ ً‬    ‫ثــم أضــاف قائ ـ ً‬\n‫الوكالــة وأقــام علــي عــدة دعــاوي كيديــة إلبطــال شــهادتي هــذا مــا‬\n‫لــدي مــن شــهادة وبعــرض حــال الشــاهد ومــا جــاء يف شــهادته علــى‬\n‫املدعــى عليــه وكالــة قــال أمــا حالــه فــا أعلــم عنــه شــيئ ًا وأمــا مــا جــاء‬\n‫يف شــهادته فشــهادته غيــر صحيحــة والشــاهد خصــم ملوكلــي وبينــه‬\n‫وبــن موكلــي دعــوى مقامــة يف احملكمــة العامــة مبكــة يف شــأن‬\n‫مالــي ويف احملكمــة اجلزائيــة يف ســب وشــتم تلفــظ بــه الشــاهد علــى‬\n‫موكلــي والدعــوى مقامــة لــدى فضيلــة الشــيخ فســألت املدعــي وكالــة‬\n‫هــل لديــك زيــادة بينــة فقــال نعــم التســجيل الصوتــي ملــا تلفــظ بــه املدعــى‬\n‫عليــه أصالــة فطلبــت مــن املدعــي وكالــة التســجيل الصوتــي فأســتعد‬\n‫بذلــك ورفعــت اجللســة ويف يــوم الثالثــاء املوافق‪1434/06/20‬هـ افتتحت‬\n‫اجللســة الســاعة (‪ )11:30‬وفيهــا حضــر الطرفــان وأبــرز املدعــي ســيدي‬\n‫ال صوتي ـ ًا للمحــاورة التــي متــت بــن الشــاهد‬      ‫قــال أنــه يتضمــن تســجي ً‬\n‫ومــوكل املدعــى عليــه وهــذا يدينــه مبــا قــذف بــه موكلتــي فأمرتــه‬\n\n\n                                                                                           ‫‪338‬‬\n\f      ‫بتســليم الســيدي للمدعــى عليــه وكالــة وطلــب املدعــى عليــه وكالــة‬\n      ‫مهلــة لســماع التســجيل والــرد عليــه ورفعــت اجللســة ففــي يــوم االثنــن‬\n      ‫املوافق‪1434/07/10‬ه ـ افتتحــت اجللســة الســاعة (‪ )09:45‬وفيهــا‬\n      ‫حضــر الطرفــان وجــرى ســؤال املدعــى عليــه وكالــة عــن جوابــه علــى مــا‬\n      ‫تضمنــه التســجيل فأجــاب بقولــه الســيدي الــذي ســلم لــي وجدتــه فارغـ ًا‬\n      ‫مــن أي مــادة مســجلة فطلبــت مــن املدعــي إعطــاء املدعــى عليــه وكالــة‬\n      ‫ســيدي أخــر فأســتعد بذلــك وقــال لــدي نســخة وســوف أشــغلها بحضــور‬\n      ‫املدعــى عليــه وكالــة يف مجلســنا هــذا للتأكــد مــن وجــود التســجيل‬\n      ‫فقــام بتشــغيل القــرص فأتضــح أن بــه مــادة مســجلة وطلــب املدعــى عليــه‬\n      ‫وكالــة مهلــة لعرضهــا علــى موكلــه ورفعــت اجللســة ففــي هــذا اليــوم‬\n      ‫األربعــاء ‪1434/07/26‬ه ـ افتتحــت اجللســة الســاعة (‪ )10:30‬وفيهــا‬\n      ‫حضــر املدعــي وكالــة واملدعــى عليــه أصالــة ‪ .....‬ســعودي اجلنســية‬\n      ‫بالســجل املدنــي رقــم (‪ ).....‬حيــث حضــرا وطلبــا إكمــال نظــر دعواهمــا‬\n      ‫فســألت املدعــى عليــه أصالــة هــل الصــوت املســجل علــى الســيدي الــذي‬\n      ‫أســتلمه وكيلــك هــو صوتــك فقــال ال فســألت املدعــي هــل لديــك زيــادة‬\n      ‫بينــة فقــال ليــس لــدي ســوى مــن أحضــرت فأفهمتــه بــأن لــه ميــن املدعــى‬\n      ‫عليــه علــى نفــي دعــواه قــال أطلــب ميينــه وبعــرض اليمــن علــى املدعــى‬\n      ‫عليــه حلــف قائــا واهلل العظيــم أننــي لــم أتلفــظ علــى املدعيــة أصالــة‬\n      ‫باأللفــاظ التــي أدعــى بهــا املدعــي وكالــة واحملــرر نصهــا يف الئحتــه‬\n      ‫واملرصــودة يف هــذا الضبــط وبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة‬\n      ‫وحيــث ال بينــة للمدعــي علــى دعــواه ســوى مــا قــدم وقــد ظهــر مــن حــرص‬\n      ‫الشــاهد علــى الشــهادة وتربصــه باملدعــى عليــه وإعــداد التســجيل لــه مــا‬\n      ‫تــرد معــه شــهادته وحيــث حلــف املدعــى عليــه علــى نفــي دعــوى املدعــي‬\n\n\n‫‪339‬‬\n\f‫فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي وأخليــت ســبيل‬\n‫املدعــى عليــه مــن هــذه الدعــوى وبعــرض احلكــم علــى املدعــي وكالــة‬\n‫قــرر اعتراضــه بالئحــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن ‪1434/10/19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة (‪ )11:30‬وفيهــا حضــر املدعــي وكالــة ولــم‬\n‫يحضــر املدعــى عليــه حيــث قــدم املدعــي الئحتــه االعتراضيــة ومت طلــب‬\n‫الطرفــن للنظــر يف الالئحــة لــذا جــرى رفــع اجللســة إلــى يــوم االثنــن‬\n‫‪1434/11/3‬ه ـ الســاعة احلاديــة عشــرة والنصــف صباح ـ ًا إلحضــار‬\n‫املدعــى عليــه ففــي يــوم االثنــن املوافــق‪ 1434/11/03‬ه ـ افتتحــت‬\n‫اجللســة الســاعة‪ 11.30‬وفيهــا حضــر الطرفــان وقــد حضــر املدعــي يف‬\n‫‪1434/8/22‬ه ـ وســلم الئحتــه االعتراضيــة ولــم يتــم ضبــط ذلــك ســهوا‬\n‫مــن الكاتــب وتضمنــت الالئحــة يف فقرتهــا ثالثــا مــا نصــه ( حيــث لدينــا‬\n‫بينــة وهــي إقــرار املدعــى عليــه بأن الصوت الوارد يف التســجيل املذكور‬\n‫هــو صوتــه وذلــك بإقــراره املرصــود يف ضبــط القضيــة املرفوعــة منــي‬\n‫ضــد املدعــى عليــه بتهمــة الســب والشــتم واملنظــورة لدى فضيلــة القاضي‬\n‫وبســؤال املدعــى عليــه أصالــة قــال مــا ادعــاه املدعــي أننــي أدليــت لــدى‬\n‫فضيلــة الشــيخ بــأن الصــوت املســجل يف الســيدي الــذي مت عرضــه‬\n‫لديكــم واســتمعته هــو صوتــي فغيــر صحيــح والصحيــح أننــي دفعــت‬\n‫بــأن بعضــه صوتــي وبعضهــا ليــس صوتــي بــل هــو دبلجــه إللصــاق التهمــة‬\n‫لــذا جــرى رفــع اجللســة للكتابــة إلــى فضيلــة الشــيخ ‪ ).....(/‬لإلفــادة‬\n‫مبــا لديــه ورفعــت اجللســة ففــي هــذا اليــوم اخلميــس ‪1434/11/13‬ه ـ‬\n‫افتتحــت اجللســة الســاعة (‪ )1:15‬وفيهــا حضــر الطرفــان وقــد وردنــا مــن‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫فضيلــة الشــيخ خطابــه رقــم ‪ 342501224‬يف ‪1434/11/13‬هـ املتضمن‬\n      ‫مــا نصــه (نفيــد فضيلتكــم بــأن املدعــي قــدم لنــا قــرص مــرن اقتطــف‬\n      ‫منــه مقاطــع باأللفــاظ التــي تلفــظ بهــا املدعــى عليــه وهــي ســبعة ألفــاظ‬\n      ‫األولــى (ابــن احلمــارة) والثانيــة (األعــور اللــي كان يتنقــور) والثالثــة (اهلل‬\n      ‫يلعنهــم عيلــه وســخه) والرابعــة (قــول للحيــوان الكلــب) واخلامســة (ال‬\n      ‫تقهرنــي ‪ ).....‬والسادســة (‪ ).....‬والســابعة (‪ .....‬احليــوان) وبســماع ذلــك‬\n      ‫ا لــم أقــل ذلــك والصــوت‬   ‫مــن املدعــى عليــه أجــاب املدعــى عليــه قائ ـ ً‬\n      ‫املوجــود يف املقطــع (ال تقهرنــي ‪ ).....‬واملقطــع (‪ .....‬احليــوان) واملقطع (اهلل‬\n      ‫يلعنهــم عيلــه وســخه) فإنــه يعــود لــي ولكنــه متذبــذب ومتغيــر وأطلــب‬\n      ‫نســخة لســماعها والتأكــد مــن بقيــة املقاطــع ويف جلســة أخــرى أنكــر‬\n      ‫املدعــى عليــه بــأن هــذا صوتــه وبعــرض ذلــك علــى املدعــي قــال أطلــب‬\n      ‫إمهالــي إلحضــار بينــة أخــرى وحيــث جــرى إمهــال املدعــي إلحضــار‬\n      ‫البينــة ودفــع بانــه ليــس لديــه ســوى مــا قــدم وحيــث تضمــن خطــاب‬\n      ‫فضيلــة الشــيخ اآلنــف ذكــره إنــكار املدعــى عليــه لصوتــه املســجل فلــم‬\n      ‫يظهــر لــي مــا يوجــب إعــادة النظــر ومــا حكمــت بــه علــى حالــه وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                ‫يف ‪1434/11/13‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n      ‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد‬\n      ‫برقــم ‪ 341208414‬وتاريــخ ‪1434/12/1‬ه ـ املرفــق بهــا القــرار رقــم‬\n      ‫‪ 34281307‬وتاريــخ ‪1434/7/26‬ه الصــادر مــن فضيلــة الشــيخ (‪).....‬‬\n\n\n‫‪341‬‬\n\f‫مســاعد رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املتضمــن دعــوى‪/‬‬\n‫(‪ ).....‬ســعودية اجلنســية ضــد‪ ).....(/‬ســعودي اجلنســية املتهــم يف قــذف‪،‬‬\n‫احملكــوم فيــه مبــا دون بباطنــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة قررنــا املوافقــة علــى احلكــم‪ ،‬واهلل املوفــق وصلــى‬\n                      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪342‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":336,"source_page_end":342,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7ca64a4d9aa3f77a2f939ef5d11dc412a3910ea46df7642319dc3fcb32fe2d6c","normalized_text_hash":"9002cdac737621e97d4eb8a6fc62a6600074de854a4d72faec756b324bb6f586","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p336-34281307"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7b29f722-3c23-55ab-869e-672eda77dc38","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم عن طريق رسالة جوال -مطالبة املدعي باملجازاة -إقرار املدعى عليه مبا جاء يف الدعوى -إدانة املدعى عليه.","document_number":"34175650","case_number":"34107315","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم عن طريق رسالة جوال -مطالبة املدعي باملجازاة -إقرار املدعى عليه مبا جاء يف الدعوى -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/1 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34175650 :‬‬\n                   ‫َر ْق ُم الدعوى‪34107315 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34235173‬تاريخه‪1434/6/10:‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والشــتم عــن طريــق رســالة‬\n‫جــوال ‪ -‬مطالبــة املدعــي باملجــازاة ‪ -‬إقــرار املدعــى عليــه مبــا جــاء يف‬\n                                               ‫الدعــوى ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n‫قــال يف كشــاف القنــاع‪« :‬كل مــا فيــه إيــذاء ليــس بصريــح يف الزنــى‬\n         ‫فيعــزر بــه الرتكابــه معصيــة وكفــا لــه عــن أذى املعصومــن»‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليــه بأنــه أرســل لــه رســالة جــوال تتضمــن‬\n‫شــتمه لــه مبــا جــاء يف دعــواه‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n‫ذلــك‪ -‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي وقــدم اعتــذاره عمــا‬\n‫بــدر منــه‪ -‬مــا أقــدم عليــه املدعــى عليــه أمــر محــرم يوجــب تعزيــره ألن‬\n‫فيــه إيــذاء لغيــره‪ -‬قضــت احملكمــة بإدانــة املدعــى عليــه مبــا نســب إليــه‬\n‫وقــررت جلــده خمــس جلــدات بحضــور املدعــي‪ -‬قنــع املدعــي باحلكــم‬\n‫وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف املوافقــة‬\n                                                                  ‫علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                      ‫‪316‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بينبــع املســاعد برقــم ‪ 34107315‬وتاريــخ ‪1434/03/04‬ه ـ‬\n      ‫واملقيــدة باحملكمــة برقــم ‪ 34562323‬وتاريــخ ‪1434/03/04‬ه ـ ففــي‬\n      ‫يــوم األربعــاء املوافــق ‪1434/03/18‬ه ـ الســاعة الثامنــة صباحــا افتتحــت‬\n      ‫اجللســة وفيها حضر ‪ ...‬املدعي ســعودي اجلنســية مبوجب الســجل املدني‬\n      ‫رقــم ‪ ....‬ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه شــرعا رغــم تبلغــه‬\n      ‫باملوعــد شــخصيا حســب إفــادة محضــري اخلصــوم برقــم ‪34562323‬‬\n      ‫يف ‪1434/03/13‬ه ـ لــذا قــررت النظــر يف الدعــوى فســألت املدعــي‬\n      ‫عــن دعــواه فقــرر قائــا ان املدعــى عليــه شــتمني عبــر رســالة جــوال‬\n      ‫وقــال عنــي اننــي واطــي اطلــب احلكــم عليــه وتعزيــره لقــاء ذلــك هــذه‬\n      ‫دعــواي وبطلــب البينــة مــن املدعــي طلــب إمهالــه إلحضارهــا فأجيــب‬\n      ‫لطلبــه ولــذا رفعــت اجللســة ‪.‬ويف يــوم االثنــن املوافــق ‪ 1434/04/01‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 08:30‬وفيهــا حضــر املدعــي وحضــر حلضــوره‬\n      ‫املدعــى عليــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وبســؤال‬\n      ‫املدعــى عليــه عمــا ذكــره املدعــي أجــاب قائــا بــأن مــا ذكــره املدعــي‬\n      ‫صحيــح وأنــا اعتــذر عمــا حصــل منــي هكــذا أجــاب وبنــاء علــى مــا ســبق‬\n      ‫مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه بصحــة مــا ذكــره املدعــي‬\n      ‫وحلرمــة ايــذاء النــاس والتلفــظ عليهــم قــال يف كشــاف القنــاع ( ‪..‬مــن‬\n      ‫كل مــا فيــه ايــذاء ليــس بصريــح يف الزنــى فيعــزر بــه الرتكابــه معصيــه‬\n      ‫وكفــا عــن أذى املعصومــن )‪ .‬لــذا فقــد ثبــت لــدي ادانــة املدعــى عليــه‬\n\n‫‪317‬‬\n\f‫بقولــة للمدعــي ( يــا واطــي ) وحكمــت عليــه بجلــده خمــس جلــدات‬\n‫بحضــور املدعــي هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم‬\n‫علــى املدعــي قــرر قناعتــه كمــا قــرر املدعــى عليــه اعتراضــه بالئحــة‬\n‫اعتراضيــه فأفهمتــه بــأن لــه مــدة ثالثــن يومــا تبــدأ مــن هــذا اليــوم فــاذا‬\n‫مضــت املــدة ولــم يتقــدم املدعــي بشــيء فــأن احلكــم يكتســب القطعيــة‬\n‫ويســقط حقــه يف االعتــراض فجــرى تســليمه صــوره مــن صــك احلكــم‪.‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬هــ‪.‬‬\n‫ويف يــوم االثنــن املوافــق ‪ 1434/06/26‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 11:15‬وفيهــا قــد عــادت املعاملــة مــن محكمــة االســتئناف مصادقــا‬\n‫عليهــا بالقــرار رقــم ‪ 34235173‬وتاريــخ ‪1434/06/10‬هـ ـ وهــذا نصــه‬\n‫(وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم وبــاهلل‬\n‫التوفيــق) قاضــي اســتئناف ‪ ....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.....‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ....‬موقــع يف األصــل ومجــاز‪ .‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                         ‫حــرر يف ‪1434/6/26‬هــ‪.‬‬\n\n\n\n\n                                                                                        ‫‪318‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":316,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"44b263014403fd5e1dd9204acac77c0167434e2bd4d222f6e4ba82ff4eb4b1e9","normalized_text_hash":"0e89257f43166f052711e59d47763495f8a7753ba2ba0416200ddc32d4ebf8d8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p316-34175650"},{"id":"b91e364c-70f7-57cb-af41-dd084eb1fa55","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إيجابية التقرير الطبي للمدعي -إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","document_number":"3455790","case_number":"34107904","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/4","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إيجابية التقرير الطبي للمدعي -إقرار املدعى عليه بالدعوى -إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/3/4 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3455790 :‬‬\n                         ‫َر ْق ُم الدعوى‪34107904 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34167375‬تاريخه‪1434/03/21 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتســبب يف إصابــة ‪-‬‬\n      ‫مطالبــة املدعــي باملجــازاة ‪ -‬إيجابيــة التقريــر الطبــي للمدعــي ‪ -‬إقــرار‬\n                               ‫املدعــى عليــه بالدعــوى ‪ -‬إدانــة املدعــى عليــه‪.‬‬\n\n\n\n                          ‫قول اهلل تعالى‪( :‬وال تعتدوا إن اهلل ال يحب املعتدين)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام باالعتــداء عليــه بالضــرب ممــا‬\n      ‫تســبب يف إصابتــه بكدمــات بالوجــه والركبتــن وســجحات بالظهــر‬\n      ‫وحتركــت بعــض أســنانه مــع نزيــف يســير بالفــم‪ ،‬ولــذا فقــد طلــب‬\n      ‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه مبــا جــاء‬\n      ‫يف الدعــوى جملــة وتفصيــا‪ -‬املدعــى عليــه أقــر بضــرب املدعــي وإحلــاق‬\n      ‫اإلصابــات املذكــورة بــه والشــرع قــد حــرم االعتــداء علــى اآلمنــن‬\n      ‫بغيــر حــق‪ -‬قضــت احملكمــة بســجن املدعــى عليــه عشــرة أيــام وجلــده‬\n      ‫خمســن جلــدة دفعــة واحــدة مــع أخــذ التعهــد عليــه بعــدم العــودة ملثــل‬\n      ‫ذلــك‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه‪ -‬قــررت‬\n                                    ‫محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n‫‪319‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34107904‬وتاريــخ‬\n‫‪1434/3/4‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34464667‬وتاريــخ‬\n‫‪1434/02/24‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/03/04‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر(‪ ).....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم(‪ ).....‬وادعــى علــى احلاضــر معــه يف مجلــس‬\n‫احلكــم (‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم(‪ ).....‬قائــا يف‬\n‫حتريــر دعــواه إنــه يف تاريــخ‪1433/06/03 :‬ه ـ ويف حــي (‪ ).....‬باملدينــة‬\n‫املنــورة قــام املدعــى عليــه باالعتــداء علــي وضربنــي بيــده علــى وجهــي‬\n‫وجنبــي عــدة ضربــات حتــى ســقطت علــى األرض وحلــق بــي كدمــات‬\n‫بالوجــه والركبتــن وســجحات بالظهــر وحتركــت بعــض أســناني مــع‬\n‫نزيــف يســير بالفــم مــن جــراء ذلــك وقــد صــدر بحقــي التقريــر الطبــي‬\n‫الصــادر مــن مستشــفى امليقــات باملدينــة املنــورة برقــم ‪23/1131/22‬‬\n‫يف ‪1433/6/3‬ه ـ وهــو متضمــن مــا ذكرتــه مــن اإلصابــات التــي حلقــت‬\n‫بــي ومــدة الشــفاء خمســة أيــام لــذا أطلــب احلكــم بتأديــب املدعــى عليــه‬\n‫لقــاء اعتدائــه وإحلــاق اإلصابــات بــي هــذه دعــواي وبســؤال املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي يف دعــواه‬ ‫عمــا جــاء يف دعــوى املدعــي أجــاب قائ ـ ً‬\n‫صحيــح ففــي التاريــخ املذكــور يف الدعــوى وقــع بينــي وبــن املدعــي‬\n‫مشــادة كالميــة متاســكنا باأليــدي وقــد ضربتــه بيــدي علــى وجهــه‬\n‫وجنبيــه فســقط علــى األرض مــن جــراء ذلــك وحلقــه اإلصابــات املبينــة‬\n\n                                                                                        ‫‪320‬‬\n\f      ‫يف دعــواه وهــي منــي دون غيــري وقــد حكــم علــي يف احلــق العــام باجللــد‬\n      ‫والســجن هكــذا أجــاب هــذا وقــد جــرى اإلطــاع علــى التقريــر الطبــي‬\n      ‫املرفــق باملعاملــة و الصــادر مــن مستشــفى امليقــات باملدينــة املنــورة برقــم‬\n      ‫‪ 23/1131/22‬يف ‪1433/06/03‬ه ـ املتضمــن إصابــة املدعــي بكدمــة‬\n      ‫بالوجه وأخرى بالركبة اليمنى وسجحات بالظهر وحترك يف األسنان‬\n      ‫ونزيــف يســير بالفــم ومــدة الشــفاء خمســة أيــام كمــا جــرى اإلطــاع‬\n      ‫علــى القــرار الشــرعي الصــادر منــي يف احلــق العــام برقــم ‪ 33446254‬يف‬\n      ‫‪1433/11/03‬ه ـ واملصــدق مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫والقاضــي بجلــد املدعــى عليــه خمســن جلــدة وســجنه عشــرة أيــام‬\n      ‫وأخــذ التعهــد عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا‬\n      ‫أن املدعــى عليــه صــادق علــى دعــوى املدعــي فأقــر باالعتــداء وضــرب‬\n      ‫املدعــي وإحلــاق اإلصابــات بــه املذكــورة آنف ـ ًا ومبــا أن الشــرع قــد حــرم‬\n      ‫االعتــداء علــى اآلمنــن بغيــر حــق فقــال ســبحانه (وال تعتــدوا إن اهلل‬\n      ‫ال يحــب املعتديــن) ومبــا أن التعزيــر يشــرع يف كل معصيــة ال حــد‬\n      ‫فيهــا وال كفــارة جلميــع مــا ذكــر فقــد حكمــت بتعزيــر املدعــى عليــه‬\n      ‫للحــق اخلــاص وذلــك بجلــده خمســن جلــدة تقــع علــى بدنــه دفعــة واحــدة‬\n      ‫ويســجن عشــرة أيــام كاملــة ويؤخــذ عليــه التعهــد بعــد م العــودة ملثــل‬\n      ‫ذلــك وبعرضــه قــرر املدعــي قناعتــه باحلكــم أمــا املدعــى عليــه فقــرر‬\n      ‫عــدم قناعتــه باحلكــم وطلــب رفعــه إلــى محكمــة االســتئناف بــدون‬\n      ‫الئحــة اعتراضيــة فأجيــب لطلبــه وقــد انتهــت اجللســة يف متــام الســاعة ‪20‬‬\n      ‫‪ 10 :‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                    ‫وســلم ‪ .‬حــرر يف ‪1434/3/4‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪ -:‬فقــد‬\n\n\n‫‪321‬‬\n\f‫جــرى منــا نحــن قضــاة الدائــرة اجلزائية الســابعة يف محكمة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34464667‬وتاريــخ‬\n‫‪1434/3/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪).....( /‬‬\n‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 3455790‬وتاريــخ‬\n‫‪1434/3/4‬ه ـ احملكــوم فيــه مبــا دون بباطــن القــرار ‪ ،‬املتضمــن دعــوى‬\n‫املدعــي العــام ضــد احلــدث‪ ( ).....( /‬العمــر‪ 16‬ســعودي اجلنســية ) املتهــم‬\n‫يف مضاربــة ‪ ،‬وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى‬\n‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                       ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪322‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":319,"source_page_end":322,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"64749e550bcb6fd1248ca31a730c7b98d3db954a9d4150df8ada41b555b288d1","normalized_text_hash":"7b9644e01509f431d160480317e00f6961f0dd08ce65e797b06928131e31b2f4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p319-3455790"},{"id":"43e22a1a-8cd7-5a19-82c7-7d441045fb6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب واللعن -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز عن إقامة البينة- مين على نفي الدعوى -رد الدعوى.","document_number":"34219039","case_number":"34149417","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/21","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب واللعن -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -عجز عن إقامة البينة- مين على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34219039 :‬‬\n                         ‫َر ْق ُم الدعوى‪34149417 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34274125‬تاريخه‪1434/07 /19 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب واللعــن ‪ -‬مطالبــة املدعــي‬\n      ‫باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬عجــز عــن إقامــة البينــة‪-‬‬\n                                       ‫ميــن علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬لــو يعطــى النــاس بدعواهــم الدعــى‬\n                ‫نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بســبه ولعــن والديــه كمــا أنــه قــام‬\n      ‫مبضايقتــه ومطاردتــه بالســيارة‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫لقــاء ذلــك ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي جملــة‬\n      ‫وتفصيــا ‪ -‬املدعــي ليــس لديــه بينــة تثبــت دعــواه وطلــب ميــن املدعــى‬\n      ‫عليــه علــى نفيهــا فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بعــدم‬\n      ‫اســتحقاق املدعــي ملــا يدعيــه لعــدم ثبــوت دعــواه‪ -‬قنــع املدعــى عليــه‬\n      ‫باحلكــم وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                           ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫‪323‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة اجلزائيــة يف‬\n‫محافظــة األحســاء املكلــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم‬\n‫‪ 34149417‬وتاريــخ ‪ 1434/04/01‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 34794771‬وتاريــخ ‪1434/4/1‬ه ـ حضــر‪ ......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ......‬وادعــى ضــد ‪ ......‬ســعودي اجلنســية مبوجــب‬\n‫ا لقــد ســبق وان قــام هــذا احلاضــر معــي‬   ‫الســجل املدنــي رقــم ‪ ......‬قائ ـ ً‬\n‫مبضايقتــي ومطاردتــي بالســيارة كمــا انــه قــام بســبي ولعــن والــدي‬\n‫اطلــب مجازاتــه لقــاء ذلــك علمــا بــأن شــقيقي متــزوج بابنــة أخ املدعــى‬\n‫عليــه وتوجــد بينهمــا عــداوة وقــد حلقنــي بتلــك العــداوة وبعــرض تلــك‬\n‫الدعــوى علــى املدعــى عليــه أجــاب قائــا ال صحــة ملــا ذكــره املدعــي‬\n‫مــن مضايقتــي لــه ومطاردتــي لــه بالســيارة كمــا ال صحــة ملــا ذكــره‬\n‫املدعــي مــن قيامــي بســبه ولعــن والــده لــذا فليــس لــه حــق عنــدي وبــرد‬\n‫ذلــك علــى املدعــي قــال الصحيــح هــو مــا ذكرتــه يف دعــواي وليــس‬\n‫لــدي بينــه واطلــب ميينــه علــى نفــي دعــواي فــان هــو حلــف فــا أطالبــه‬\n‫بشــي بخصــوص هــذه الدعــوى وبعــرض ذلــك علــى املدعــى عليــه اســتعد‬\n‫بــأداء اليمــن وأداهــا قائــا واهلل العظيــم أننــي لــم أضايــق ‪ ......‬هــذا‬\n‫احلاضــر معــي ولــم أطــارده بالســيارة ولــم أقــم بســبه ولعــن والــده لــذا‬\n‫وبعــد ســماع الدعــوى واإلجابــة وحيــث طلــب املدعــي مجــازاة املدعــى‬\n‫عليــه لقــاء مضايقتــي لــه ومطاردتــي لــه بالســيارة وقيامــه بســبه ولعــن‬\n‫والــده وإن املدعــى عليــه قــد انكــر ذلــك وإنــه ال بينــة لــدى املدعــي علــى‬\n‫دعــواه وإن املدعــي قــد طلــب ميــن خصمــه علــى نفــي دعــواه وإن املدعــى‬\n\n                                                                                       ‫‪324‬‬\n\f      ‫عليــه قــد اســتعد بــأداء اليمــن وأداهــا ولقولــه عليــه الصــاة والســام‬\n      ‫(لــو يعطــى النــاس بدعواهــم الدعــى أنــاس دمــاء رجــال وأموالهــم ولكــن‬\n      ‫اليمــن علــى املدعــى عليــه ) وملــا هــو مقــرر شــرع ًا مــن أن اليمــن تقطــع‬\n      ‫اخلصومــة يف احلــال لــذا فقــد حكمــت بعــدم اســتحقاق املدعــي ‪......‬‬\n      ‫لدعــواه ضــد ‪ ......‬لعــدم ثبوتهــا وبذلــك حكمــت وبعرضــه قــرر املدعــي‬\n      ‫عــدم قناعتــه بــه وطلــب تقــدمي الئحــة اعتراضيــة فجــرى إفهامــه بأنــه‬\n      ‫ســوف يتــم تســليمه صــورة مــن القــرار الشــرعي هــذا اليــوم وإن لــه مــدة‬\n      ‫ثالثــن يوم ـ ًا تبــدأ مــن تاريــخ اســتالمه بعدهــا يســقط حقــه يف تقــدمي‬\n      ‫الالئحــة أمــا املدعــى عليــه فقــرر قناعتــه بــه وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n      ‫الشــيخ‪ ......‬برقــم ‪ 34/794771‬وتاريــخ ‪1434/7/3‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلته املســجل برقــم ‪ 34219039‬وتاريــخ ‪1434/5/21‬هـ‬\n      ‫اخلــاص بدعــوى ‪ ......‬ضــد ‪ ......‬يف قضيــة ســب أو شــتم وقــد تضمن القرار‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكم واهلل املوفق وصلى‬\n       ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪14347/7/18‬هــ‪.‬‬\n\n\n\n\n‫‪325‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":323,"source_page_end":325,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5ea5ec760788dbe00ba537fefc4651a8072d3066596eb008ef196afe87a3d0bc","normalized_text_hash":"87338e19764b9839441b9d5c08f1a9d1e3b3af9a37942c4432bcb929139e43fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p323-34219039"},{"id":"3fd49eca-2447-5ef9-b635-b4b16138e7bb","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب واتهام الشرف -مطالبة املدعية باملجازاة -إنكار املدعي عليه الدعوى -افتقاد املدعية البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34259492","case_number":"34176629","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/4","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب واتهام الشرف -مطالبة املدعية باملجازاة -إنكار املدعي عليه الدعوى -افتقاد املدعية البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1433/7/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34259492 :‬‬\n                   ‫َر ْق ُم الدعوى‪34176629 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34300798‬تاريخه‪1434/8/21 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب واتهــام الشــرف ‪ -‬مطالبــة‬\n‫املدعيــة باملجــازاة ‪ -‬إنــكار املدعــي عليــه الدعــوى ‪ -‬افتقــاد املدعيــة‬\n       ‫البينــة ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                  ‫مــن أنكــر)‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليــه قــام بالتلفــظ عليهــا وذلــك باتهــام‬\n‫شــرفها حيــث ذكــر أن أحــد األشــخاص يكثــر دخولــه وخروجــه إلــى‬\n‫شــقتها وأن هنــاك ســيارات مختلفــة تركــب معهــا كمــا أنــه ينظــر إليهــا‬\n‫بحــدة وال يغــض بصــره عنهــا‪ ،‬ولــذا فقــد طلبــت احلكــم عليــه بعقوبــة‬\n‫تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعيــة‬\n‫جملــة وتفصيــا‪ -‬طلبــت احملكمــة مــن املدعيــة أن تقــدم بينتهــا علــى‬\n‫دعواهــا فعجــزت عــن ذلــك وطلبــت ميــن املدعــى عليــه علــى نفيهــا فأداها‬\n‫طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى‬\n‫املدعيــة‪ -‬عارضــت املدعيــة علــى احلكــم‪ -‬قــررت محكمــة االســتئناف‬\n                                          ‫باألكثريــة املوافقــة علــى احلكــم‪.‬‬\n\n                                                                                  ‫‪326‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34176629‬وتاريــخ‬\n      ‫‪ 1434/4/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34942251‬وتاريــخ‬\n      ‫‪1434/4/16‬ه ففــي يــوم الثالثــاء املوافق‪1434/06/20‬ه ـ افتتحــت‬\n      ‫اجللســة وفيهــا حضــرت املدعيــة ‪ ....‬ســعودية بالســجل املدنــي رقــم‪.....‬‬\n      ‫واملعــرف بهــا مــن قبــل ابنهــا (‪ ).....‬ســعودي بالســجل املدنــي رقــم (‪).....‬‬\n      ‫وحضــر املدعــى عليــه (‪ ).....‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬وادعــت‬\n      ‫املدعيــة قائل ـ ًة إن املدعــى عليــه يســكن يف إحــدى شــقق العمــارة التــي‬\n      ‫أســكن فيهــا وقــد اعتــدى علــى خصوصيتــي واتهــم شــريف حيــث ذكــر‬\n      ‫أن أحــد األشــخاص ويعمــل مدرس ـ ًا كثــر دخولــه وخروجــه لشــقتي‬\n      ‫وهنــاك ســيارات أشــكال وألــوان أركــب معهــا وبلــغ أحــد ســكان‬\n      ‫العمــارة أنــه ســيقوم بإبــاغ الهيئــة عنــي كمــا أنــه ينظــر إلــي بحــدة وال‬\n      ‫يغــض بصــره وقلــت لــه غــض البصــر فقــال أبنظــر إليــك أطلــب إثبــات‬\n      ‫إدانتــه بذلــك وتعزيــره هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫ا مــا ذكرتــه املدعيــة غيــر صحيــح ســوى أنــي ســألت وهــو‬    ‫أجــاب قائ ـ ً‬\n      ‫أحــد ســكان العمــارة عــن رجــل يدخــل ويخــرج يف العمــارة فقــال لــي‬\n      ‫إن هــذا مــدرس خصوصــي يأتــي ليــدرس أبنــاء املدعيــة هــذه إجابتــي‬\n      ‫وبســؤال املدعيــة هــل لديــك بينــة علــى ذلــك فقالــت نعــم وأطلــب مهلــة‬\n      ‫إلحضارهــا هكــذا أجابــت وعليــه رفعــت اجللســة لذلــك ويف يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/07/04‬ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعيــة‬\n\n‫‪327‬‬\n\f‫واملعــرف بهــا مــن قبــل ابنهــا وبســؤالها عــن بينتهــا فقالــت طلبــت مــن‬\n‫الشــاهد احلضــور ورفــض أطلــب ميــن املدعــى عليــه علــى نفــي دعــواي‬\n‫هــذه إجابتــي وبعــرض ذلــك علــى املدعــى عليــه قــال مســتعد ببــذل اليمــن‬\n‫ا بعــد إذنــي لــه وبعــد تخويفــه مبــآالت اليمــن الكاذبــة‬       ‫فحلــف قائ ـ ً‬\n‫(واهلل الــذي ال إلــه إال هــو الــذي يعلــم الســر وأخفــى أنــي غــاض بصــري‬\n‫عــن ولــم أتهمهــا بشــرفها هكــذا أحلــف ) فبنــاء علــى مــا ســلف مــن‬\n‫الدعــوى واإلجابــة وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا محضــر‬\n‫االســتدالل الصــادر مــن شــرطة التنعيــم مبكــة ونظــرا إلنــكار املدعــى‬\n‫عليــه دعــوى املدعيــة ولعــدم تقــدمي املدعيــة بينــة علــى دعواهــا ولطلبهــا‬\n‫ميــن املدعــى عليــه وحللــف املدعــى عليــه علــى نفــي دعــوى املدعيــة ولقولــه‬\n‫صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن أنكــر) ملــا‬\n‫ســبق كلــه فقــد صرفــت النظــر عــن دعــوى املدعيــة وبعــرض ذلــك عليهــا‬\n‫قــررت االعتــراض بالئحــة وجــرى تســليمها صــورة مــن القــرار الشــرعي‬\n‫وأفهمــت بنظــام االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/4‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم (‪ )34942251‬وتاريخ‬\n‫‪1434/8/9‬ه املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪).....(/‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة برقــم (‪)34259492‬‬\n‫وتاريــخ ‪1434/7/4‬ه املتضمــن دعــوى املدعيــة (‪ ).....‬ســعودية اجلنســية‬\n‫ضــد (‪ ).....‬ســعودي اجلنســية بشــأن ســب وشــتم‪ ،‬احملكــوم فيــه مبــا دون‬\n\n\n                                                                                      ‫‪328‬‬\n\f      ‫بباطــن القــرار‪ ،‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫قررنــا باألكثريــة املوافقــة علــى احلكــم‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل‬\n                                  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":326,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cf2b72f29817e4113e24da8d4b46d13f0a0a5dba3efe2f862d35038e75bb46fc","normalized_text_hash":"7bd04e4e06234e9ebb25b6bdcdfa6bdace5649780f164df5ced4ce2320103e0c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p326-34259492"},{"id":"80294ed8-f57d-5fe5-b6df-5078d21fdcb3","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ أمام مجلس القضاء -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -رد شهادة الوكيل ملوكله فيما هو وكيل فيه -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34248488","case_number":"34221527","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/21","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ أمام مجلس القضاء -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -رد شهادة الوكيل ملوكله فيما هو وكيل فيه -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/21 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34248488 :‬‬\n                   ‫َر ْق ُم الدعوى‪34221527 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34296772‬تاريخه‪1434/8 /14 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والتلفــظ أمــام مجلــس‬\n‫القضــاء ‪ -‬مطالبــة املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى‬\n‫‪ -‬بينــة املدعــي غيــر موصلــة‪ -‬رد شــهادة الوكيــل ملوكلــه فيمــا هــو‬\n‫وكيــل فيــه‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n                      ‫‪ -1‬قول اهلل تعالى‪(( :‬وأشهدوا ذوي عدل منكم ))‪.‬‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                           ‫علــى مــن أنكــر)‪.‬‬\n‫‪ -3‬قــول ابــن قدامــة رحمــه اهلل يف املغنــي (‪« :)258/7‬وال تقبــل شــهادته‬\n               ‫لــه‪-‬أي الوكيــل ملوكلــه‪ -‬فيمــا هــو وكيــل فيــه ‪..‬إلــخ»‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه قــام بســبه والتلفــظ عليــه مبــا جــاء يف‬\n‫دعــواه وذلــك أثنــاء ترافعهمــا أمــام إحــدى احملاكــم‪ ،‬وطلــب احلكــم‬\n‫عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف‬\n‫دعــوى املدعــي ســوى أنــه أثنــاء نظــر قضيــة حضانــة أقامهــا املدعــي‬\n‫ا عــن ابنتــه‪ :‬هــل املدعــي أهــل للحضانــة؟‬  ‫ســأله القاضــي بصفتــه وكيـ ً‬\n‫ا للحضانــة فهــو متهــاون يف الصــاة وكثيــر‬        ‫فأجــاب بأنــه ليــس أه ـ ً‬\n\n                                                                                     ‫‪330‬‬\n\f      ‫الســفر‪ -‬طلبــت احملكمــة مــن املدعــي أن يقــدم بينتــه علــى دعــواه‬\n      ‫فأحضــر شــاهدين إال أن احملكمــة قــررت رد شــهادة األول منهمــا‬\n      ‫ألنــه وكيــل للمدعــي يف كال القضيتــن ورد شــهادة الثانــي ألنــه عجــز‬\n      ‫عــن إحضــار معدلــن لــه‪ -‬طلــب املدعــي ميــن املدعــى عليــه علــى نفــي‬\n      ‫دعــواه فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بعــدم ثبــوت دعــوى‬\n      ‫املدعــي جتــاه املدعــى عليــه‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n             ‫املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا (‪ ).....‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر‬\n      ‫برقــم ‪ 34221527‬وتاريــخ ‪1434/05/13‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 341177869‬وتاريــخ ‪1434/05/13‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافق‪1434/06/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر‬\n      ‫‪ ....‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬وادعــى علــى احلاضــر ‪ ....‬ســعودي‬\n      ‫ال يف دعواه إن املدعى عليه والد طليقتي‬           ‫بالســجل املدني رقم (‪ ).....‬قائ ً‬\n      ‫وهــو خالــي شــقيق والدتــي وقــد أقمــت دعــوى يف احملكمــة العامــة ضــد‬\n      ‫طليقتــي بطلــب حضانــة ابنتــي وعمرهــا ثــاث ســنوات وكان موعــد‬\n      ‫اجللسة هو ‪1434/5/12‬هـ لدى القاضي باحملكمة العامة باخلبر (‪).....‬‬\n      ‫ا عــن ابنتــه وقــد قــال املدعــى عليــه عنــي‬\n                                                     ‫وقــد حضــر املدعــى عليــه وكيـ ً‬\n      ‫يف مجلــس القضــاء بأنــي ســكير نكيــر راعــي دســكوات ومراقــص‬\n      ‫ـاء عليــه أطلــب تأديبــه لقــاء ســبه وشــتمه لــي‬  ‫وغيــر صالــح للتربيــة وبنـ ً‬\n‫‪331‬‬\n\f‫بهــذا الــكالم هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب‬\n‫بقولــه إن املدعــي ابــن شــقيقتي وقــد تــزوج ابنتــي قبــل خمــس ســنوات‬\n‫تقريبـ ًا وحصــل الطــاق بينهمــا قبــل ســنتني تقريبـ ًا وبينهمــا بنــت اســمها‬\n‫(‪ ).....‬عمرهــا ثــاث ســنوات وهــي لــدى والدتهــا ابنتــي وقــد أقــام املدعــي‬\n‫ا عــن ابنتــي‬‫دعــوى ضــد ابنتــي يطلــب حضانــة ابنتهمــا فحضــرت وكيـ ً‬\n‫يف تاريــخ ‪1434/5/12‬ه ـ لــدى القاضــي يف احملكمــة العامــة باخلبــر‬\n‫(‪ ).....‬وقــد ســألني القاضــي هــل املدعــي أهــل للحضانــة فقلــت إنــه ليــس‬\n‫ا للحضانــة فهــو متهــاون يف الصــاة وكثيــر الســفر هــذا مــا قلتــه‬       ‫أه ـ ً‬\n‫ال متهــاون يف الصالة وكثير‬        ‫فقــط بعــد ســؤال القاضــي لــي واملدعــي فع ً‬\n‫الســفر وهــو يعلــم ذلــك هكــذا أجــاب وبعــرض ذلــك علــى املدعــي قــال‬\n‫نعــم أنــا كثيــر الســفر لــ‪ .........‬لكــن معظــم ســفري لــ‪ .........‬مــع أهلــي‬\n‫وأحيان ـ ًا أســافر لوحــدي وأحيان ـ ًا مــع بعــض الشــباب وأحضــر قاعــات‬\n‫الســينما وأشــاهد األفــام فيهــا أفــام حركيــة ورومانســية وحــروب‬\n‫وأمــا الصــاة فصــاة الفجــر أصليهــا إذا اســتيقظت للــدوام ويف هــذه‬\n‫األيــام أصليهــا عنــد الســابعة إال ربــع بعــد خــروج وقتهــا وذلــك ألنــي ال‬\n‫أســتيقظ للــدوام إال يف هــذا الوقــت وباقــي الصلــوات أصليهــا يف وقتهــا‬\n‫يف املســجد وأمــا مــا ذكــره املدعــي مــن أنــه لــم يتلفــظ باأللفــاظ التــي‬\n‫ذكرتهــا يف دعــواي فغيــر صحيــح ولــدي شــاهدين علــى صحــة كالمــي‬\n‫وهمــا حاضريــن معــي وأطلــب ســماع شــهادتهما ثــم حضــر (‪ ).....‬ســعودي‬\n‫بالســجل املدنــي رقــم (‪ ).....‬وبســؤاله عمــا لديــه مــن شــهادة قــال إنــي‬\n‫اعمــل يف مكتــب القاضــي يف احملكمــة العامــة باخلبــر (‪ ).....‬ويف شــهر‬\n‫جمــادى األولــى ال أذكــر التاريــخ كان هنــاك جلســة لــدى الشــيخ‬\n‫ا عــن ابنتــه يف‬‫وطــريف الدعــوى همــا املدعــي واملدعــى عليــه (‪ ).....‬وكيـ ً‬\n\n\n                                                                                       ‫‪332‬‬\n\f      ‫قضيــة حضانــة وكنــت متواجــد ًا يف املكتب وســمعت الشــيخ يســأل هل‬\n      ‫ا حلضانــة البنــت فقــال املدعــى عليــه راعــي بحريــن هــذا مــا‬ ‫املدعــي أهـ ً‬\n      ‫لــدي مــن شــهادة كمــا (‪).....‬حضــر ســعودي بالســجل املدنــي رقــم (‪).....‬‬\n      ‫وبســؤاله عمــا لديــه مــن شــهادة قــال إنــي وكيــل للمدعــي وقــد أقــام‬\n      ‫دعــوى يف احملكمــة العامــة ضــد طليقتــه بشــأن حضانــة ابنتهــا وقــد‬\n      ‫وكلنــي يف الترافــع بالدعــوى وحضرنــا لــدى الشــيخ وقــد ســأل الشــيخ‬\n      ‫ا للحضانــة فقــال إنــه ســكير نكيــر‬        ‫املدعــى عليــه هــل املدعــى أه ـ ً‬\n      ‫راعــي بنــات راعــي مراقــص وبــ‪ ........‬هــذا مــا لــدي مــن شــهادة هكــذا‬\n      ‫شــهدا وبســؤال املدعــي ألديــك زيــادة بينــة فقــال ال يوجــد لــدي شــهود‬\n      ‫غيــر هذيــن الشــاهدين وبعــرض الشــاهدين وشــهادتهما علــى املدعــى‬\n      ‫عليــه قــال أمــا الشــاهد األول فــا أعلــم عــن حالــه وقــد يكــون بينــه‬\n      ‫وبــن املدعــي (‪ ).....‬عالقــة وشــهادته غيــر صحيحــة وال أقبــل بهــا وأمــا‬\n      ‫الشــاهد فهــو وكيــل املدعــي يف القضيــة املقامــة يف احملكمــة العامــة‬\n      ‫وكذلــك وكيلــه يف هــذه القضيــة فهــو مــن أقــام الدعــوى عنــه وكتــب‬\n      ‫صحيفــة الدعــوى فهــذه الشــهادة فيهــا مصلحــة لــه فهــو يهمــه كســب‬\n      ‫القضيــة للفائــدة املاديــة واملعنويــة وشــهادته غيــر صحيحــة وال أقبــل بهــا‬\n      ‫هكــذا قــرر وبعــرض ذلــك علــى الشــاهدين قال الشــاهد ال يوجد لي أي‬\n      ‫عالقــة باملدعــي وقــال الشــاهد نعــم أنــا وكيــل للمدعــي (‪ ).....‬يف هــذه‬\n      ‫القضيــة وقــد قــام موظــف مكتبــي بكتابــة صحيفــة الدعــوى والتقــدم‬\n      ‫بهــا للترافــع عنــه وكذلــك وكيلــه يف القضيــة املنظــورة لــدى الشــيخ‬\n      ‫هكــذا قــرر وبطلــب معدلــن للشــاهد (‪ ).....‬قــال الشــاهد (‪ ).....‬أنــا ال‬\n      ‫أســتطيع إحضــار معدلــن لــي ولــن أحضرهــم هكــذا قــرر ثــم أقفلــت‬\n      ‫اجللســة الســاعة العاشــرة للتأمــل وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n\n\n‫‪333‬‬\n\f‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم األربعــاء ‪1434/6/21‬ه ـ‬\n‫الســاعة الثامنــة والنصــف افتتحــت اجللســة بحضــور املدعــي واملدعــى‬\n‫عليــه وجــرى افهــام املدعــي بــأن لــه ميــن املدعــى عليــه (‪ ).....‬علــى نفــي‬\n‫دعــواه فقــال أنــا أطلبهــا وأقبــل بهــا وبعــرض اليمــن علــى املدعــى عليــه‬\n‫ا واهلل العظيــم أنــي لــم أقــل عــن‬‫اســتعد بهــا ثــم أذنــت لــه فحلــف قائ ـ ً‬\n‫املدعــي أنــه ســكير نكيــر راعــي دســكوات ومراقــص وغيــر صالــح‬\n‫للتربيــة وذلــك اثنــاء نظــر الدعــوى لــدى القاضــي يف احملكمــة العامــة‬\n‫ـاء علــى مــا تقــدم مــن‬‫باخلبــر الشــيخ واهلل العظيــم هكــذا حلــف فبنـ ً‬\n‫الدعــوى واإلجابــة وحيــث أنكــر املدعــى عليــه الدعــوى وال بينــة مثبتــة‬\n‫للمدعــي علــى دعــواه وأمــا الشــاهد فقــد قــرر بأنــه ال يســتطيع احضــار‬\n‫معدلــن وقــد قــرر العلمــاء رحمهــم اهلل تعالــى بــأن مــن شــروط الشــاهد‬\n‫العدالــة لقــول اهلل تعالى((وأشــهدوا ذوي عــدل منكــم ))وأمــا الشــاهد‬\n‫فهــو وكيــل للمدعــي وهــو مــن كان يترافــع عنــه لــدى الشــيخ ويدعــي‬\n‫بــأن املدعــى عليــه صــدرت منــه األلفــاظ محــل الدعــوى وهــو كذلــك‬\n‫مــن كتــب صحيفــة الدعــوى يف هــذه القضيــة فهــو يف احلقيقــة خصــم‬\n‫للمدعــى عليــه قــال ابــن قدامــه رحمــه اهلل يف املغنــي(‪(( :)258/7‬وال‬\n‫تقبــل شــهادته لــه‪-‬أي الوكيــل ملوكلــه‪ -‬فيمــا هــو وكيــل فيــه ألنــه‬\n‫يثبــت لنفســه حقــا بدليــل أنــه إذا وكلــه يف قبــض حــق فشــهد بــه لــه ثبــت‬\n‫اســتحقاق قبضــه وألنــه خصــم فيــه بدليــل أنــه ميلــك املخاصمــة فيــه))‪.‬‬\n‫وحيــث حلــف املدعــى عليــه علــى نفــي الدعــوى ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم((البينة علــى املدعــي واليمــن علــى مــن أنكــر)) لــذا‬\n‫فقــد حكمــت بعــدم ثبــوت دعــوى املدعــي جتــاه املدعــى عليــه وبعــرض‬\n‫احلكــم علــى الطرفــن قنــع املدعــى عليــه ولــم يقنــع املدعــي واســتعد‬\n\n\n                                                                                      ‫‪334‬‬\n\f      ‫بتقــدمي الئحــة اعتراضيــة فأفهــم مبراجعــة احملكمــة يــوم الســبت‬\n      ‫‪1434/6/24‬ه ـ الســتالم صــورة احلكــم وتقــدمي اعتراضــه خــال ثالثني‬\n      ‫يوم ـ ًا إن لــم يقدمــه ســقط حقــه يف االعتــراض كمــا قــررت الكتابــة‬\n      ‫لدائــرة التحقيــق واالدعــاء العــام إلكمــال الــازم حيــال املدعــي لتهاونــه‬\n      ‫يف صــاة الفجــر وأقفلــت اجللســة الســاعة التاســعة وصلــى اهلل وســلم‬\n                                                                  ‫علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم االربعــاء ‪1434/7/26‬ه ـ‬\n      ‫الســاعة الثانيــة عشــر والنصــف افتتحــت اجللســة وقــد انتهــت املــدة‬\n      ‫النظاميــة لالعتــراض ولــم يقــدم املدعــي الئحتــه االعتراضيــة لــذا فقــد‬\n      ‫ســقط حقــه يف االعتــراض وقــررت إحالــة املعاملــة حملكمــة االســتئناف‬\n                         ‫لتدقيــق احلكــم وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n      ‫‪ 34/1177869‬وتاريــخ ‪1434/7/29‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 341892585‬وتاريــخ ‪1434/8/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪34248488‬‬\n      ‫وتاريــخ ‪1434/6/21‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‪ ).....(/‬يف قضيــة‬\n      ‫قــذف وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                               ‫يف ‪1434/8/13‬هــ‪.‬‬\n\n\n\n‫‪335‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":330,"source_page_end":335,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"27397edd83202ea6ee00292cebbb93c1ecc692c9bed7c8c90f155f40c4fb2593","normalized_text_hash":"bfcd90a573e2750c747d55b18d10ee605de122b12aec76dc90c0a15a537a14c9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p330-34248488"},{"id":"175d99c0-d98f-5f44-8ef5-1bcc5c2b9f49","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعى غير موصلة -رد شهادة -مين املدعى عليه على نفي الدعوى -رد","document_number":"34281307","case_number":"34228115","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة يف شأن مالي ويف المحكمة اجلزائية يف سب وشتم تلفظ به الشاهد على موكلي و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/26","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعى غير موصلة -رد شهادة -مين املدعى عليه على نفي الدعوى -رد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34281307 :‬‬\n                   ‫َر ْق ُم الدعوى‪34228115 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34380493‬تاريخه‪1434/12/18 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص) ‪ -‬اعتــداء بالقــذف والســب والشــتم ‪-‬‬\n‫مطالبــة املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــى‬\n‫غيــر موصلــة ‪ -‬رد شــهادة ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى ‪ -‬رد‬\n                                                                        ‫الدعــوى‪.‬‬\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه قــام بقــذف موكلتــه ووصفهــا‬\n‫بالــكالم البــذيء املذكــور يف دعــواه‪ ،‬وطلــب احلكــم عليــه بحــد‬\n‫القــذف لقــاء ذلــك‪ -‬أنكــر وكيــل املدعــى عليــه مــا جــاء يف دعــوى‬\n‫املدعــي جملــة وتفصيــا‪ -‬طلبــت احملكمــة مــن وكيــل املدعيــة أن‬\n‫يقــدم بينتــه علــى دعــواه فأحضــر شــاهد ًا واحــد ًا إال أن احملكمــة قــررت‬\n‫رد شــهادته لظهــور تربصــه باملدعــى عليــه‪ ،‬كمــا قــدم تســجيال صوتيـ ًا‬\n‫لــم يثبــت أنــه بصــوت املدعــى عليــه‪ ،‬ومــؤدى ذلــك أن بينتــه غيــر موصلــة‬\n‫إلثبــات دعــواه ‪-‬طلــب وكيــل املدعيــة ميــن املدعــى عليــه على نفــي دعواه‬\n‫فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بصــرف النظر عــن دعوى‬\n\n\n                                                                                     ‫‪336‬‬\n\f      ‫املدعيــة وأخلــت ســبيل املدعــى عليــه منهــا‪ -‬عــارض وكيــل املدعيــة علــى‬\n                 ‫احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬مســاعد رئيــس احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34228115‬وتاريــخ‬\n      ‫‪1434/5/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341208414‬وتاريــخ‬\n      ‫‪1434/5/18‬ه ـ ففــي يــوم الســبت املوافــق ‪1434/6/3‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة (‪ )10:30‬للنظــر يف دعــوى املدعيــة وفيهــا حضــر املدعــي‬\n      ‫وكالــة ‪ .....‬بالســجل املدنــي رقــم (‪ ).....‬وأدعــى علــى ‪ ....‬بالســجل املدنــي‬\n      ‫رقــم (‪ ).....‬بالوكالــة عــن (‪ ).....‬ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫ا يف دعــواه عليــه قــام املدعــى عليــه أصالــة بالتلفــظ علــى‬      ‫(‪ ).....‬قائ ـ ً‬\n      ‫والدتــي باأللفــاظ التاليــة (مهــي كويســه وأنهــا كانــت تتكلــم معــاه‬\n      ‫يف أمــور مــا هــي كويســه ) (احلرمــة كانــت نيتهــا خبيثــة واآلدميــة فيهــا‬\n      ‫حاجــه غلــط وأنــه كان يجبلهــا الهدايــا) (‪( ).....‬أن املدعــى عليــه كان‬\n      ‫جالــس مــع يف بيتهــم وكانــت البســه شرشــف صــاة وقامــت وضمتــه‬\n      ‫قــدام عيالهــا) وتفــوه بهــذه األلفــاظ يف منتــزه ‪ .......‬بطريــق مكــة جــدة‬\n      ‫يف ‪2012/10/14‬م أطلــب احلكــم عليــه بإقامــة حــد القــذف بحقــه‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه وكالــة قــال مــا ادعــاه املدعــي غيــر‬\n      ‫ا وبطلــب البينــة مــن املدعــي أحضــر للشــهادة‬      ‫صحيــح جمل ـ ًة وتفصي ـ ً‬\n      ‫وأدائهــا ‪ .........‬بالســجل املدنــي رقــم (‪ ).....‬املولــود يف ‪1402/1/15‬ه ـ‬\n      ‫وبســؤاله عــن مقــر ســكنه وعالقتــه باملدعيــة قــال أســكن يف مكــة‬\n\n‫‪337‬‬\n\f‫ا كنــت يف‬     ‫وال تربطنــي باملدعيــة أي عالقــة وباستشــهاده شــهد هلل قائـ ً‬\n‫منتــزه ‪ ......‬يف طريــق مكــة جــدة مــع املدعــى عليــه أصالــة وكنــت قــد‬\n‫أعــددت جهــاز جوالــي علــى خاصيــة التســجيل لســبق صــدور الــكالم‬\n‫البــذيء مــن املدعــى عليــه وقــد كان بينــي وبينــه نقــاش حــول بعــض‬\n‫املشــاكل بــن املدعيــة واملدعــى عليــه وقــد ســمعته يقــول عــن املدعيــة‬\n‫(مهــي كويســه وأنهــا كانــت تتكلــم معــاه يف أمــور مــا هــي كويســه‬\n‫) (احلرمــة كانــت نيتهــا خبيثــة واآلدميــة فيهــا حاجــه غلــط وأنــه كان‬\n‫يجبلهــا الهدايــا) (‪( ).....‬أن املدعــى عليــه كان جالــس مــع (‪ ).....‬يف‬\n‫بيتهــم وكانــت البســه شرشــف صــاة وقامــت وضمتــه قــدام عيالهــا)‬\n‫ا للمدعــى عليــه وقــد ســحب منــي‬        ‫ا وأنــا كنــت وكي ـ ً‬    ‫ثــم أضــاف قائ ـ ً‬\n‫الوكالــة وأقــام علــي عــدة دعــاوي كيديــة إلبطــال شــهادتي هــذا مــا‬\n‫لــدي مــن شــهادة وبعــرض حــال الشــاهد ومــا جــاء يف شــهادته علــى‬\n‫املدعــى عليــه وكالــة قــال أمــا حالــه فــا أعلــم عنــه شــيئ ًا وأمــا مــا جــاء‬\n‫يف شــهادته فشــهادته غيــر صحيحــة والشــاهد خصــم ملوكلــي وبينــه‬\n‫وبــن موكلــي دعــوى مقامــة يف احملكمــة العامــة مبكــة يف شــأن‬\n‫مالــي ويف احملكمــة اجلزائيــة يف ســب وشــتم تلفــظ بــه الشــاهد علــى‬\n‫موكلــي والدعــوى مقامــة لــدى فضيلــة الشــيخ فســألت املدعــي وكالــة‬\n‫هــل لديــك زيــادة بينــة فقــال نعــم التســجيل الصوتــي ملــا تلفــظ بــه املدعــى‬\n‫عليــه أصالــة فطلبــت مــن املدعــي وكالــة التســجيل الصوتــي فأســتعد‬\n‫بذلــك ورفعــت اجللســة ويف يــوم الثالثــاء املوافق‪1434/06/20‬هـ افتتحت‬\n‫اجللســة الســاعة (‪ )11:30‬وفيهــا حضــر الطرفــان وأبــرز املدعــي ســيدي‬\n‫ال صوتي ـ ًا للمحــاورة التــي متــت بــن الشــاهد‬      ‫قــال أنــه يتضمــن تســجي ً‬\n‫ومــوكل املدعــى عليــه وهــذا يدينــه مبــا قــذف بــه موكلتــي فأمرتــه‬\n\n\n                                                                                           ‫‪338‬‬\n\f      ‫بتســليم الســيدي للمدعــى عليــه وكالــة وطلــب املدعــى عليــه وكالــة‬\n      ‫مهلــة لســماع التســجيل والــرد عليــه ورفعــت اجللســة ففــي يــوم االثنــن‬\n      ‫املوافق‪1434/07/10‬ه ـ افتتحــت اجللســة الســاعة (‪ )09:45‬وفيهــا‬\n      ‫حضــر الطرفــان وجــرى ســؤال املدعــى عليــه وكالــة عــن جوابــه علــى مــا‬\n      ‫تضمنــه التســجيل فأجــاب بقولــه الســيدي الــذي ســلم لــي وجدتــه فارغـ ًا‬\n      ‫مــن أي مــادة مســجلة فطلبــت مــن املدعــي إعطــاء املدعــى عليــه وكالــة‬\n      ‫ســيدي أخــر فأســتعد بذلــك وقــال لــدي نســخة وســوف أشــغلها بحضــور‬\n      ‫املدعــى عليــه وكالــة يف مجلســنا هــذا للتأكــد مــن وجــود التســجيل‬\n      ‫فقــام بتشــغيل القــرص فأتضــح أن بــه مــادة مســجلة وطلــب املدعــى عليــه‬\n      ‫وكالــة مهلــة لعرضهــا علــى موكلــه ورفعــت اجللســة ففــي هــذا اليــوم‬\n      ‫األربعــاء ‪1434/07/26‬ه ـ افتتحــت اجللســة الســاعة (‪ )10:30‬وفيهــا‬\n      ‫حضــر املدعــي وكالــة واملدعــى عليــه أصالــة ‪ .....‬ســعودي اجلنســية‬\n      ‫بالســجل املدنــي رقــم (‪ ).....‬حيــث حضــرا وطلبــا إكمــال نظــر دعواهمــا‬\n      ‫فســألت املدعــى عليــه أصالــة هــل الصــوت املســجل علــى الســيدي الــذي‬\n      ‫أســتلمه وكيلــك هــو صوتــك فقــال ال فســألت املدعــي هــل لديــك زيــادة‬\n      ‫بينــة فقــال ليــس لــدي ســوى مــن أحضــرت فأفهمتــه بــأن لــه ميــن املدعــى‬\n      ‫عليــه علــى نفــي دعــواه قــال أطلــب ميينــه وبعــرض اليمــن علــى املدعــى‬\n      ‫عليــه حلــف قائــا واهلل العظيــم أننــي لــم أتلفــظ علــى املدعيــة أصالــة‬\n      ‫باأللفــاظ التــي أدعــى بهــا املدعــي وكالــة واحملــرر نصهــا يف الئحتــه‬\n      ‫واملرصــودة يف هــذا الضبــط وبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة‬\n      ‫وحيــث ال بينــة للمدعــي علــى دعــواه ســوى مــا قــدم وقــد ظهــر مــن حــرص‬\n      ‫الشــاهد علــى الشــهادة وتربصــه باملدعــى عليــه وإعــداد التســجيل لــه مــا‬\n      ‫تــرد معــه شــهادته وحيــث حلــف املدعــى عليــه علــى نفــي دعــوى املدعــي‬\n\n\n‫‪339‬‬\n\f‫فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي وأخليــت ســبيل‬\n‫املدعــى عليــه مــن هــذه الدعــوى وبعــرض احلكــم علــى املدعــي وكالــة‬\n‫قــرر اعتراضــه بالئحــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن ‪1434/10/19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة (‪ )11:30‬وفيهــا حضــر املدعــي وكالــة ولــم‬\n‫يحضــر املدعــى عليــه حيــث قــدم املدعــي الئحتــه االعتراضيــة ومت طلــب‬\n‫الطرفــن للنظــر يف الالئحــة لــذا جــرى رفــع اجللســة إلــى يــوم االثنــن‬\n‫‪1434/11/3‬ه ـ الســاعة احلاديــة عشــرة والنصــف صباح ـ ًا إلحضــار‬\n‫املدعــى عليــه ففــي يــوم االثنــن املوافــق‪ 1434/11/03‬ه ـ افتتحــت‬\n‫اجللســة الســاعة‪ 11.30‬وفيهــا حضــر الطرفــان وقــد حضــر املدعــي يف‬\n‫‪1434/8/22‬ه ـ وســلم الئحتــه االعتراضيــة ولــم يتــم ضبــط ذلــك ســهوا‬\n‫مــن الكاتــب وتضمنــت الالئحــة يف فقرتهــا ثالثــا مــا نصــه ( حيــث لدينــا‬\n‫بينــة وهــي إقــرار املدعــى عليــه بأن الصوت الوارد يف التســجيل املذكور‬\n‫هــو صوتــه وذلــك بإقــراره املرصــود يف ضبــط القضيــة املرفوعــة منــي‬\n‫ضــد املدعــى عليــه بتهمــة الســب والشــتم واملنظــورة لدى فضيلــة القاضي‬\n‫وبســؤال املدعــى عليــه أصالــة قــال مــا ادعــاه املدعــي أننــي أدليــت لــدى‬\n‫فضيلــة الشــيخ بــأن الصــوت املســجل يف الســيدي الــذي مت عرضــه‬\n‫لديكــم واســتمعته هــو صوتــي فغيــر صحيــح والصحيــح أننــي دفعــت‬\n‫بــأن بعضــه صوتــي وبعضهــا ليــس صوتــي بــل هــو دبلجــه إللصــاق التهمــة‬\n‫لــذا جــرى رفــع اجللســة للكتابــة إلــى فضيلــة الشــيخ ‪ ).....(/‬لإلفــادة‬\n‫مبــا لديــه ورفعــت اجللســة ففــي هــذا اليــوم اخلميــس ‪1434/11/13‬ه ـ‬\n‫افتتحــت اجللســة الســاعة (‪ )1:15‬وفيهــا حضــر الطرفــان وقــد وردنــا مــن‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫فضيلــة الشــيخ خطابــه رقــم ‪ 342501224‬يف ‪1434/11/13‬هـ املتضمن‬\n      ‫مــا نصــه (نفيــد فضيلتكــم بــأن املدعــي قــدم لنــا قــرص مــرن اقتطــف‬\n      ‫منــه مقاطــع باأللفــاظ التــي تلفــظ بهــا املدعــى عليــه وهــي ســبعة ألفــاظ‬\n      ‫األولــى (ابــن احلمــارة) والثانيــة (األعــور اللــي كان يتنقــور) والثالثــة (اهلل‬\n      ‫يلعنهــم عيلــه وســخه) والرابعــة (قــول للحيــوان الكلــب) واخلامســة (ال‬\n      ‫تقهرنــي ‪ ).....‬والسادســة (‪ ).....‬والســابعة (‪ .....‬احليــوان) وبســماع ذلــك‬\n      ‫ا لــم أقــل ذلــك والصــوت‬   ‫مــن املدعــى عليــه أجــاب املدعــى عليــه قائ ـ ً‬\n      ‫املوجــود يف املقطــع (ال تقهرنــي ‪ ).....‬واملقطــع (‪ .....‬احليــوان) واملقطع (اهلل‬\n      ‫يلعنهــم عيلــه وســخه) فإنــه يعــود لــي ولكنــه متذبــذب ومتغيــر وأطلــب‬\n      ‫نســخة لســماعها والتأكــد مــن بقيــة املقاطــع ويف جلســة أخــرى أنكــر‬\n      ‫املدعــى عليــه بــأن هــذا صوتــه وبعــرض ذلــك علــى املدعــي قــال أطلــب‬\n      ‫إمهالــي إلحضــار بينــة أخــرى وحيــث جــرى إمهــال املدعــي إلحضــار‬\n      ‫البينــة ودفــع بانــه ليــس لديــه ســوى مــا قــدم وحيــث تضمــن خطــاب‬\n      ‫فضيلــة الشــيخ اآلنــف ذكــره إنــكار املدعــى عليــه لصوتــه املســجل فلــم‬\n      ‫يظهــر لــي مــا يوجــب إعــادة النظــر ومــا حكمــت بــه علــى حالــه وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                ‫يف ‪1434/11/13‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n      ‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد‬\n      ‫برقــم ‪ 341208414‬وتاريــخ ‪1434/12/1‬ه ـ املرفــق بهــا القــرار رقــم‬\n      ‫‪ 34281307‬وتاريــخ ‪1434/7/26‬ه الصــادر مــن فضيلــة الشــيخ (‪).....‬‬\n\n\n‫‪341‬‬\n\f‫مســاعد رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املتضمــن دعــوى‪/‬‬\n‫(‪ ).....‬ســعودية اجلنســية ضــد‪ ).....(/‬ســعودي اجلنســية املتهــم يف قــذف‪،‬‬\n‫احملكــوم فيــه مبــا دون بباطنــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة قررنــا املوافقــة علــى احلكــم‪ ،‬واهلل املوفــق وصلــى‬\n                      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪342‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":336,"source_page_end":342,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7ca64a4d9aa3f77a2f939ef5d11dc412a3910ea46df7642319dc3fcb32fe2d6c","normalized_text_hash":"9002cdac737621e97d4eb8a6fc62a6600074de854a4d72faec756b324bb6f586","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p336-34281307"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
